INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('fa1276e1-ef82-590f-aa73-d4f7973f53f0', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 35, 35, 'Some of those who stood by, when they heard it, said, "Behold, he is calling Elijah."'),
  ('48d068e6-c3ea-5fbb-a911-5e731e227e3a', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 36, 36, 'One ran, and filling a sponge full of vinegar, put it on a reed, and gave it to him to drink, saying, "Let him be. Let''s see whether Elijah comes to take him down."'),
  ('ca9c860d-0011-5004-a84a-931da5410bb9', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 37, 37, 'Jesus cried out with a loud voice, and gave up the spirit.'),
  ('393a9a30-29d3-506c-a07b-857940b0aecf', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 38, 38, 'The veil of the temple was torn in two from the top to the bottom.'),
  ('4468b950-a20e-5e90-ae63-08744cd536d7', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 39, 39, 'When the centurion, who stood by opposite him, saw that he cried out like this and breathed his last, he said, "Truly this man was the Son of God!"'),
  ('58be9f8f-c551-598d-aea5-9b6a02003f5e', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 40, 40, 'There were also women watching from afar, among whom were both Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;'),
  ('ae362a29-34c4-5930-abd1-2c0fe4de2da9', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 41, 41, 'who, when he was in Galilee, followed him, and served him; and many other women who came up with him to Jerusalem.'),
  ('a0432cc4-d5ad-5d69-a522-11569462caab', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 42, 42, 'When evening had now come, because it was the Preparation Day, that is, the day before the Sabbath,'),
  ('0dfc028f-cab7-5e8f-a3cd-bc5bd7454206', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 43, 43, 'Joseph of Arimathaea, a prominent council member who also himself was looking for the Kingdom of God, came. He boldly went in to Pilate, and asked for Jesus'' body.'),
  ('06455096-e857-55a1-ac9c-a4fa01479a69', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 44, 44, 'Pilate marveled if he were already dead; and summoning the centurion, he asked him whether he had been dead long.'),
  ('3e484c72-7873-5101-ab05-4e4c2d9e68c7', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 45, 45, 'When he found out from the centurion, he granted the body to Joseph.'),
  ('9813d98d-043f-50c8-ae02-680423aa7eb3', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 46, 46, 'He bought a linen cloth, and taking him down, wound him in the linen cloth, and laid him in a tomb which had been cut out of a rock. He rolled a stone against the door of the tomb.'),
  ('b35ef585-17c6-502b-ac87-a02a7b1ee898', '7836e82a-df94-54d1-ae97-55c5eeecaef8', NULL, 47, 47, 'Mary Magdalene and Mary, the mother of Joses, saw where he was laid.'),
  ('6f539ca2-c1a3-5392-a3c0-1cf0b43b6060', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 1, 1, 'When the Sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, bought spices, that they might come and anoint him.'),
  ('3927160b-f438-5f84-a60c-e8227d238d06', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 2, 2, 'Very early on the first day of the week, they came to the tomb when the sun had risen.'),
  ('787469cf-3e12-5ddf-a5f0-4231f2bb3674', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 3, 3, 'They were saying among themselves, "Who will roll away the stone from the door of the tomb for us?"'),
  ('41aaaf4e-17f3-5887-a678-60c07f43f556', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 4, 4, 'for it was very big. Looking up, they saw that the stone was rolled back.'),
  ('23b6755d-5836-5e4f-a4bf-ed13636037e9', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 5, 5, 'Entering into the tomb, they saw a young man sitting on the right side, dressed in a white robe, and they were amazed.'),
  ('167c8f6b-9dc0-5f68-a9cb-039021ce6893', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 6, 6, 'He said to them, "Don''t be amazed. You seek Jesus, the Nazarene, who has been crucified. He has risen. He is not here. Behold, the place where they laid him!'),
  ('56fe7074-4e1b-55b4-acc3-983ad37f1b56', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 7, 7, 'But go, tell his disciples and Peter, ''He goes before you into Galilee. There you will see him, as he said to you.''"'),
  ('e4312d0d-a3f3-52ec-a190-baa88b4f3df8', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 8, 8, 'They went out, and fled from the tomb, for trembling and astonishment had come on them. They said nothing to anyone; for they were afraid.'),
  ('3ed67d81-a736-51a7-a7b8-d16bd191aac3', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 9, 9, 'Now when he had risen early on the first day of the week, he appeared first to Mary Magdalene, from whom he had cast out seven demons.'),
  ('c7204e9d-3cee-5328-a02d-317edd403654', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 10, 10, 'She went and told those who had been with him, as they mourned and wept.'),
  ('50ac729d-ca98-5b32-a724-11d2ba6dc96f', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 11, 11, 'When they heard that he was alive, and had been seen by her, they disbelieved.'),
  ('79759af6-7d5d-50f1-ac96-040dfe9f6b1b', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 12, 12, 'After these things he was revealed in another form to two of them, as they walked, on their way into the country.'),
  ('67b4e911-9c71-575f-aeb0-3c3247b2cf87', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 13, 13, 'They went away and told it to the rest. They didn''t believe them, either.'),
  ('ffe60bed-da59-57fe-a954-721d6e1c9ec4', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 14, 14, 'Afterward he was revealed to the eleven themselves as they sat at the table, and he rebuked them for their unbelief and hardness of heart, because they didn''t believe those who had seen him after he had risen.'),
  ('89a05fa3-efe0-58e2-a307-c309d4341ed1', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 15, 15, 'He said to them, "Go into all the world, and preach the Good News to the whole creation.'),
  ('ddaa6157-59ef-548a-a7d2-e07a9429edab', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 16, 16, 'He who believes and is baptized will be saved; but he who disbelieves will be condemned.'),
  ('2161d605-df37-5f43-aaf7-1575b1934d1f', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 17, 17, 'These signs will accompany those who believe: in my name they will cast out demons; they will speak with new languages;'),
  ('f1240d69-914c-590b-a603-35e1fb1a4787', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 18, 18, 'they will take up serpents; and if they drink any deadly thing, it will in no way hurt them; they will lay hands on the sick, and they will recover."'),
  ('1118fdc5-9bbd-53da-aab8-63f8185bf2e0', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 19, 19, 'So then the Lord, after he had spoken to them, was received up into heaven, and sat down at the right hand of God.'),
  ('d0be51b3-8fe8-53cd-ac5f-24f59c3b9191', 'e3dc8419-f854-5def-ab88-aa848b3d2429', NULL, 20, 20, 'They went out, and preached everywhere, the Lord working with them, and confirming the word by the signs that followed. Amen.'),
  ('a391b6dd-e991-5227-a4c2-a09e123f0594', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 1, 1, 'Since many have undertaken to set in order a narrative concerning those matters which have been fulfilled among us,'),
  ('4ae500cc-fafc-5880-a1ba-0c9b7802d06d', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 2, 2, 'even as those who from the beginning were eyewitnesses and servants of the word delivered them to us,'),
  ('fd5a7081-58f7-59d4-a616-53a785f1131d', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 3, 3, 'it seemed good to me also, having traced the course of all things accurately from the first, to write to you in order, most excellent Theophilus;'),
  ('5f2aceec-455c-501d-acdb-a8c612a24e67', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 4, 4, 'that you might know the certainty concerning the things in which you were instructed.'),
  ('fe23cbee-f33d-50b7-a984-11778e26fd0a', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 5, 5, 'There was in the days of Herod, the king of Judea, a certain priest named Zacharias, of the priestly division of Abijah. He had a wife of the daughters of Aaron, and her name was Elizabeth.'),
  ('143376b3-c553-5d92-a493-76bc7a45b49a', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 6, 6, 'They were both righteous before God, walking blamelessly in all the commandments and ordinances of the Lord.'),
  ('92040c95-ab7a-57ed-a708-46b190f9240e', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 7, 7, 'But they had no child, because Elizabeth was barren, and they both were well advanced in years.'),
  ('e1cc39c4-a17c-5038-a97e-7289b83814d0', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 8, 8, 'Now it happened, while he executed the priest''s office before God in the order of his division,'),
  ('d9294660-b700-5ff5-a37d-d2580c3d6bc6', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 9, 9, 'according to the custom of the priest''s office, his lot was to enter into the temple of the Lord and burn incense.'),
  ('1e1629a4-c616-5cfa-a917-aa969f655a90', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 10, 10, 'The whole multitude of the people were praying outside at the hour of incense.'),
  ('8bc631c4-2d0f-5ffc-a06d-53bf7578ccb7', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 11, 11, 'An angel of the Lord appeared to him, standing on the right side of the altar of incense.'),
  ('e79d70c7-68f6-55e1-ab97-8fa89bb71c65', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 12, 12, 'Zacharias was troubled when he saw him, and fear fell upon him.'),
  ('a3f55075-562b-5694-a050-504fe5636949', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 13, 13, 'But the angel said to him, "Don''t be afraid, Zacharias, because your request has been heard, and your wife, Elizabeth, will bear you a son, and you shall call his name John.'),
  ('63dc0c6b-1f79-5703-a655-e15e9ab2826d', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 14, 14, 'You will have joy and gladness; and many will rejoice at his birth.'),
  ('6739fbe2-2b60-5575-ac40-09dfa7944b84', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 15, 15, 'For he will be great in the sight of the Lord, and he will drink no wine nor strong drink. He will be filled with the Holy Spirit, even from his mother''s womb.'),
  ('68854b4f-62dc-5d0d-a904-7afe8c5a64a1', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 16, 16, 'He will turn many of the children of Israel to the Lord, their God.'),
  ('39e18b3c-ceca-5f85-a7a6-641b6d559bb8', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 17, 17, 'He will go before him in the spirit and power of Elijah, ''to turn the hearts of the fathers to the children,'' and the disobedient to the wisdom of the just; to prepare a people prepared for the Lord."'),
  ('ddc5d3f8-1d61-51f3-a592-33585cdbcc1f', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 18, 18, 'Zacharias said to the angel, "How can I be sure of this? For I am an old man, and my wife is well advanced in years."'),
  ('0fd0e983-3451-5c5f-ab04-a1cc40fdbcaf', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 19, 19, 'The angel answered him, "I am Gabriel, who stands in the presence of God. I was sent to speak to you, and to bring you this good news.'),
  ('a1783ffd-ef9e-5910-a746-dd19e5a9d4a4', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 20, 20, 'Behold, you will be silent and not able to speak, until the day that these things will happen, because you didn''t believe my words, which will be fulfilled in their proper time."'),
  ('153405e6-883a-5a08-a1f9-cedb74f7984f', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 21, 21, 'The people were waiting for Zacharias, and they marveled that he delayed in the temple.'),
  ('31f9024c-9ec1-5658-ab35-ed6a775e23f6', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 22, 22, 'When he came out, he could not speak to them, and they perceived that he had seen a vision in the temple. He continued making signs to them, and remained mute.'),
  ('ef1ecded-5bdf-581d-ab17-f3310530d2e3', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 23, 23, 'It happened, when the days of his service were fulfilled, he departed to his house.'),
  ('670ae308-972e-5684-a271-864336f655e8', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 24, 24, 'After these days Elizabeth, his wife, conceived, and she hid herself five months, saying,'),
  ('c0fd0ea1-73de-592c-aa2d-2794d67bb25d', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 25, 25, '"Thus has the Lord done to me in the days in which he looked at me, to take away my reproach among men."'),
  ('833f460e-46a9-5cd0-a643-234debffe87e', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 26, 26, 'Now in the sixth month, the angel Gabriel was sent from God to a city of Galilee, named Nazareth,'),
  ('f75957df-20f8-5e74-a861-08c04d51ef8e', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 27, 27, 'to a virgin pledged to be married to a man whose name was Joseph, of the house of David. The virgin''s name was Mary.'),
  ('785cb133-9595-54fb-aaed-dedc59494595', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 28, 28, 'Having come in, the angel said to her, "Rejoice, you highly favored one! The Lord is with you. Blessed are you among women!"'),
  ('bd1c9b80-d9af-504e-a3ef-91c7d3fcf3b8', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 29, 29, 'But when she saw him, she was greatly troubled at the saying, and considered what kind of salutation this might be.'),
  ('a08b426a-c6e5-519d-a65a-321030c36596', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 30, 30, 'The angel said to her, "Don''t be afraid, Mary, for you have found favor with God.'),
  ('8d6cda45-e8d4-5ef3-a656-a5b8e156352f', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 31, 31, 'Behold, you will conceive in your womb, and bring forth a son, and will call his name ''Jesus.'''),
  ('1e8a4a73-0b80-5a18-a3c2-ede1eec2d9e5', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 32, 32, 'He will be great, and will be called the Son of the Most High. The Lord God will give him the throne of his father, David,'),
  ('e5fc9314-7776-55a1-a3c5-f573ff2aadd1', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 33, 33, 'and he will reign over the house of Jacob forever. There will be no end to his Kingdom."'),
  ('37b5d828-76e3-50c1-a676-dc458219b387', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 34, 34, 'Mary said to the angel, "How can this be, seeing I am a virgin?"'),
  ('8025e7af-4209-5332-a281-bca752f3a64d', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 35, 35, 'The angel answered her, "The Holy Spirit will come on you, and the power of the Most High will overshadow you. Therefore also the holy one who is born from you will be called the Son of God.'),
  ('0969103a-613c-5bb8-a3ad-d414f9845de1', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 36, 36, 'Behold, Elizabeth, your relative, also has conceived a son in her old age; and this is the sixth month with her who was called barren.'),
  ('bb63bbf2-07fb-550a-aa24-35283a50b7b1', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 37, 37, 'For everything spoken by God is possible."'),
  ('76abaf54-3895-5e48-a48b-f11d4bd792b6', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 38, 38, 'Mary said, "Behold, the handmaid of the Lord; be it to me according to your word." The angel departed from her.'),
  ('bc5c533a-66c4-5401-a050-fb5e774ae9a6', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 39, 39, 'Mary arose in those days and went into the hill country with haste, into a city of Judah,'),
  ('64496378-a048-5b5a-a4a1-a4954b0e0f39', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 40, 40, 'and entered into the house of Zacharias and greeted Elizabeth.'),
  ('a788920e-81b7-57f6-a161-b29dbf79745b', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 41, 41, 'It happened, when Elizabeth heard Mary''s greeting, that the baby leaped in her womb, and Elizabeth was filled with the Holy Spirit.'),
  ('dd8728dd-b4e9-54dc-a2c9-9a6a71b63c16', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 42, 42, 'She called out with a loud voice, and said, "Blessed are you among women, and blessed is the fruit of your womb!'),
  ('83027c43-013b-5f37-a3fc-64d7f08a93b3', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 43, 43, 'Why am I so favored, that the mother of my Lord should come to me?'),
  ('be54d9af-5e1c-58d6-a06c-768948185a25', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 44, 44, 'For behold, when the voice of your greeting came into my ears, the baby leaped in my womb for joy!'),
  ('24bb094b-6938-5504-a277-c7770abd0027', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 45, 45, 'Blessed is she who believed, for there will be a fulfillment of the things which have been spoken to her from the Lord!"'),
  ('28720edb-35ce-5be0-a1db-c68f46b1314e', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 46, 46, 'Mary said, "My soul magnifies the Lord.'),
  ('bebadbba-8d68-5bee-a771-03e2c5b1a460', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 47, 47, 'My spirit has rejoiced in God my Savior,'),
  ('b6e82b0b-ce14-5a9d-a195-2fc6d388e47a', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 48, 48, 'for he has looked at the humble state of his handmaid. For behold, from now on, all generations will call me blessed.'),
  ('210e08aa-cffd-5c2c-a2e7-016587f98be7', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 49, 49, 'For he who is mighty has done great things for me. Holy is his name.'),
  ('a4d3e52c-f64b-5679-a655-658cda7ab903', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 50, 50, 'His mercy is for generations of generations on those who fear him.'),
  ('0532f2a2-5a27-5e9f-a14b-dba5e089cc90', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 51, 51, 'He has shown strength with his arm. He has scattered the proud in the imagination of their hearts.'),
  ('b97590cf-33db-5939-a369-7d842ebdeb59', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 52, 52, 'He has put down princes from their thrones. And has exalted the lowly.'),
  ('1216ae8f-cd90-512e-ae1e-ba1129ffdddc', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 53, 53, 'He has filled the hungry with good things. He has sent the rich away empty.'),
  ('784e5e41-bad7-5f47-add8-051fc72de4b3', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 54, 54, 'He has given help to Israel, his servant, that he might remember mercy,'),
  ('84a8aca7-9840-5786-a5c7-ea4184311c00', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 55, 55, 'As he spoke to our fathers, to Abraham and his seed forever."'),
  ('16754640-aabd-5042-ade4-ec276259d243', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 56, 56, 'Mary stayed with her about three months, and then returned to her house.'),
  ('402a3e55-c764-5a31-a140-4f3a8517a440', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 57, 57, 'Now the time that Elizabeth should give birth was fulfilled, and she brought forth a son.'),
  ('b99d2996-4160-516f-a4f7-85ed1057c433', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 58, 58, 'Her neighbors and her relatives heard that the Lord had magnified his mercy towards her, and they rejoiced with her.'),
  ('9ab71946-07ac-5db7-aef8-7240dc086b70', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 59, 59, 'It happened on the eighth day, that they came to circumcise the child; and they would have called him Zacharias, after the name of the father.'),
  ('85bda22d-0247-54bf-a238-1e285334854c', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 60, 60, 'His mother answered, "Not so; but he will be called John."'),
  ('061c3385-6acb-54d5-a52f-ac76f3eac269', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 61, 61, 'They said to her, "There is no one among your relatives who is called by this name."'),
  ('d73951c9-668c-5d16-abfa-8e13f63e3e55', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 62, 62, 'They made signs to his father, what he would have him called.'),
  ('596f295f-fdaf-51e0-ab39-9de585a11909', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 63, 63, 'He asked for a writing tablet, and wrote, "His name is John." They all marveled.'),
  ('04c87832-658f-5ee8-a877-7ebb51a07177', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 64, 64, 'His mouth was opened immediately, and his tongue freed, and he spoke, blessing God.'),
  ('99862834-5c3c-5e50-ad21-5c5fe91f22db', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 65, 65, 'Fear came on all who lived around them, and all these sayings were talked about throughout all the hill country of Judea.'),
  ('b983afa0-b6e5-57e9-a1a8-ca9015cdd8c0', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 66, 66, 'All who heard them laid them up in their heart, saying, "What then will this child be?" The hand of the Lord was with him.'),
  ('2b637b3a-4b84-5047-a747-71147ccf676a', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 67, 67, 'His father, Zacharias, was filled with the Holy Spirit, and prophesied, saying,'),
  ('0164664a-2339-5e9b-a4f6-07457d04e31c', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 68, 68, '"Blessed be the Lord, the God of Israel, for he has visited and worked redemption for his people;'),
  ('bc364a9e-924c-5c51-affe-dad3b721026e', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 69, 69, 'and has raised up a horn of salvation for us in the house of his servant David'),
  ('73e1d920-0776-5604-af0d-aabcd851ceac', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 70, 70, '(as he spoke by the mouth of his holy prophets who have been from of old),'),
  ('1b3b9570-b120-56ac-a273-bdff6ef98fd7', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 71, 71, 'salvation from our enemies, and from the hand of all who hate us;'),
  ('0ddf42ed-0cdb-599b-a671-903eb5b93fee', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 72, 72, 'to show mercy towards our fathers, to remember his holy covenant,'),
  ('dda69426-a6c8-58af-a4a0-d8db8f7566a5', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 73, 73, 'the oath which he spoke to Abraham, our father,'),
  ('add597d8-efac-50a8-ac8e-8086bf3dd02b', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 74, 74, 'to grant to us that we, being delivered out of the hand of our enemies, should serve him without fear,'),
  ('4416d753-89d9-5239-a555-353d2fdc00c4', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 75, 75, 'In holiness and righteousness before him all the days of our life.'),
  ('0eb1c2c1-9ea1-511e-a05e-4f0e9653b39c', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 76, 76, 'And you, child, will be called a prophet of the Most High, for you will go before the face of the Lord to prepare his ways,'),
  ('b015ee08-4bb9-552f-a93f-d9344c5a8f3b', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 77, 77, 'to give knowledge of salvation to his people by the remission of their sins,'),
  ('48c9ffc8-2c58-51bd-a878-91df43416359', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 78, 78, 'because of the tender mercy of our God, whereby the dawn from on high will visit us,'),
  ('b3cc08de-e51b-50bf-afd2-bba8f181673c', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 79, 79, 'to shine on those who sit in darkness and the shadow of death; to guide our feet into the way of peace."'),
  ('64d22df1-d2a8-52d8-aa78-a5b41a5a5b11', 'a572ea00-b803-5155-a143-e5e27d68051e', NULL, 80, 80, 'The child was growing, and becoming strong in spirit, and was in the desert until the day of his public appearance to Israel.'),
  ('625e6aad-bf18-5c1f-a174-fee47ae53503', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 1, 1, 'Now it happened in those days, that a decree went out from Caesar Augustus that all the world should be enrolled.'),
  ('b6882b89-42ab-5f02-ab41-f1491638fa85', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 2, 2, 'This was the first enrollment made when Quirinius was governor of Syria.'),
  ('f4b22362-94a5-5782-a721-79fed2148fd0', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 3, 3, 'All went to enroll themselves, everyone to his own city.'),
  ('f19e0031-6c5c-5506-a089-3da01420fb64', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 4, 4, 'Joseph also went up from Galilee, out of the city of Nazareth, into Judea, to the city of David, which is called Bethlehem, because he was of the house and family of David;'),
  ('9c3177d5-4117-5923-a0bb-e09ec2b77c78', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 5, 5, 'to enroll himself with Mary, who was pledged to be married to him as wife, being pregnant.'),
  ('32cc0f28-8fda-5478-aafa-052972eabc54', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 6, 6, 'It happened, while they were there, that the day had come that she should give birth.'),
  ('be329525-91a0-5d44-a1f4-95f2d88bb31a', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 7, 7, 'She brought forth her firstborn son, and she wrapped him in bands of cloth, and laid him in a feeding trough, because there was no room for them in the inn.'),
  ('8d1935aa-95ae-523a-a342-cbd144eb3ed2', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 8, 8, 'There were shepherds in the same country staying in the field, and keeping watch by night over their flock.'),
  ('17978fb4-0754-5f16-a9eb-7da2fc5c46ca', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 9, 9, 'Behold, an angel of the Lord stood by them, and the glory of the Lord shone around them, and they were terrified.'),
  ('7606ed4a-ff14-5afa-a714-c260aba3ca1e', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 10, 10, 'The angel said to them, "Don''t be afraid, for behold, I bring you good news of great joy which will be to all the people.'),
  ('a03063ab-e499-5a83-a790-23abf95e796d', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 11, 11, 'For there is born to you, this day, in the city of David, a Savior, who is Christ the Lord.'),
  ('d8e07b87-318f-55fc-adf4-daeb2a9873f4', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 12, 12, 'This is the sign to you: you will find a baby wrapped in strips of cloth, lying in a feeding trough."'),
  ('34a1500b-a476-5acd-a616-434a4a88e5dd', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 13, 13, 'Suddenly, there was with the angel a multitude of the heavenly army praising God, and saying,'),
  ('2a1753d5-5d91-5316-a155-c1a8aa79cc5d', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 14, 14, '"Glory to God in the highest, on earth peace, good will toward men."'),
  ('80434d22-6ba6-52ca-a95d-4feefde13007', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 15, 15, 'It happened, when the angels went away from them into the sky, that the shepherds said one to another, "Let''s go to Bethlehem, now, and see this thing that has happened, which the Lord has made known to us."'),
  ('4240e887-a351-5efd-aef4-74ac3d1ee0f5', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 16, 16, 'They came with haste, and found both Mary and Joseph, and the baby was lying in the feeding trough.'),
  ('c0192277-dbe3-5477-aa55-b461c70bdf04', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 17, 17, 'When they saw it, they publicized widely the saying which was spoken to them about this child.'),
  ('4862a667-3e8e-5b50-aaa4-bed5f27bff8a', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 18, 18, 'All who heard it wondered at the things which were spoken to them by the shepherds.'),
  ('5ce87cc9-4dc3-570e-a395-7ab4b10d3a5b', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 19, 19, 'But Mary kept all these sayings, pondering them in her heart.'),
  ('bcb7a494-0c75-545e-a772-5a4242499306', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 20, 20, 'The shepherds returned, glorifying and praising God for all the things that they had heard and seen, just as it was told them.'),
  ('01697e91-d56a-512b-a626-2787b8f26ce3', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 21, 21, 'When eight days were fulfilled for the circumcision of the child, his name was called Jesus, which was given by the angel before he was conceived in the womb.'),
  ('b1796fc5-366e-5f48-ac79-8efb8f6536d8', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 22, 22, 'When the days of their purification according to the law of Moses were fulfilled, they brought him up to Jerusalem, to present him to the Lord'),
  ('777076a7-c05f-5732-add0-3d5cc6d1c0c2', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 23, 23, '(as it is written in the law of the Lord, "Every male who opens the womb shall be called holy to the Lord"),'),
  ('059e9340-e212-5980-ae55-ccd75c3c6407', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 24, 24, 'and to offer a sacrifice according to that which is said in the law of the Lord, "A pair of turtledoves, or two young pigeons."'),
  ('2b62a11b-dcad-5565-ab1a-c2a2e95e0a89', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 25, 25, 'Behold, there was a man in Jerusalem whose name was Simeon. This man was righteous and devout, looking for the consolation of Israel, and the Holy Spirit was on him.'),
  ('2b9e4f50-ff7c-5dce-ac01-f32c2ce1e84a', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 26, 26, 'It had been revealed to him by the Holy Spirit that he should not see death before he had seen the Lord''s Christ.'),
  ('fe3f7117-5fb4-57ae-a149-4dd24d747c1d', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 27, 27, 'He came in the Spirit into the temple. When the parents brought in the child, Jesus, that they might do concerning him according to the custom of the law,'),
  ('d55c503e-6bf6-5163-a6d5-333f6be6c7d8', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 28, 28, 'then he received him into his arms, and blessed God, and said,'),
  ('40e77169-de2f-518f-a34f-a94c4c4d8c7f', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 29, 29, '"Now you are releasing your servant, Master, according to your word, in peace;'),
  ('dc5a8c4c-64f2-59ac-a93c-d9575361530a', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 30, 30, 'for my eyes have seen your salvation,'),
  ('c33e8cc6-64d7-5e58-a85e-0803af569201', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 31, 31, 'which you have prepared before the face of all peoples;'),
  ('d534ae16-fcc5-589c-a965-1096192418bc', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 32, 32, 'a light for revelation to the nations, and the glory of your people Israel."'),
  ('b7f5dcc2-fbb2-5e9e-a1c3-d9033880c787', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 33, 33, 'Joseph and his mother were marveling at the things which were spoken concerning him,'),
  ('7f1e8531-bf05-5042-ac08-3d3ed4c0dae8', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 34, 34, 'and Simeon blessed them, and said to Mary, his mother, "Behold, this child is set for the falling and the rising of many in Israel, and for a sign which is spoken against.'),
  ('64c71df0-9df5-57e7-ae81-09b69f924569', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 35, 35, 'Yes, a sword will pierce through your own soul, that the thoughts of many hearts may be revealed."'),
  ('badeaa83-14ae-5799-afde-21ee30c34552', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 36, 36, 'There was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Asher (she was of a great age, having lived with a husband seven years from her virginity,'),
  ('e8635409-d7de-53a9-af38-ef45215602d5', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 37, 37, 'and she had been a widow for about eighty-four years), who didn''t depart from the temple, worshipping with fastings and petitions night and day.'),
  ('da879d9e-2593-53a7-a109-5c58efd4b20b', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 38, 38, 'Coming up at that very hour, she gave thanks to the Lord, and spoke of him to all those who were looking for redemption in Jerusalem.'),
  ('1de3e0c6-1684-5ea8-afb9-72dc82cdd5f5', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 39, 39, 'When they had accomplished all things that were according to the law of the Lord, they returned into Galilee, to their own city, Nazareth.'),
  ('9c838f4a-631e-5255-af13-8c52b7e83191', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 40, 40, 'The child was growing, and was becoming strong in spirit, being filled with wisdom, and the grace of God was upon him.'),
  ('4b98ac8e-c34e-540d-ae33-5d51b6b94c93', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 41, 41, 'His parents went every year to Jerusalem at the feast of the Passover.'),
  ('4de6a4b6-651a-5d29-a335-128836ca0983', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 42, 42, 'When he was twelve years old, they went up to Jerusalem according to the custom of the feast,'),
  ('6cc7dba0-0e90-5615-aa80-af26b49f0aeb', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 43, 43, 'and when they had fulfilled the days, as they were returning, the boy Jesus stayed behind in Jerusalem. Joseph and his mother didn''t know it,'),
  ('eb59e30d-32d0-5e76-a469-7e87a340467a', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 44, 44, 'but supposing him to be in the company, they went a day''s journey, and they looked for him among their relatives and acquaintances.'),
  ('545442c5-cb69-585e-ab1f-800e4447ef2e', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 45, 45, 'When they didn''t find him, they returned to Jerusalem, looking for him.'),
  ('dd11ffd4-bd0c-58ad-a09a-6fc1d79da329', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 46, 46, 'It happened after three days they found him in the temple, sitting in the midst of the teachers, both listening to them, and asking them questions.'),
  ('7e6f479b-438c-5df6-af5f-522387a9b6d8', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 47, 47, 'All who heard him were amazed at his understanding and his answers.'),
  ('f54797ee-1e1d-56e0-abd5-78e0587e47f3', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 48, 48, 'When they saw him, they were astonished, and his mother said to him, "Son, why have you treated us this way? Behold, your father and I were anxiously looking for you."'),
  ('7a08e3ba-89b6-5179-a873-d44e1caff3d2', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 49, 49, 'He said to them, "Why were you looking for me? Didn''t you know that I must be in my Father''s house?"'),
  ('979be186-eed3-5ea3-a104-cccb2096382e', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 50, 50, 'They didn''t understand the saying which he spoke to them.'),
  ('ae73e9c8-d023-5fca-aca6-df5814ecd226', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 51, 51, 'And he went down with them, and came to Nazareth. He was subject to them, and his mother kept all these sayings in her heart.'),
  ('6b659b7e-e942-5350-aecc-19879c34a645', '9cd68e3e-5f9a-58d7-a6e3-67fc1441bb3b', NULL, 52, 52, 'And Jesus increased in wisdom and stature, and in favor with God and men.'),
  ('edd5a12c-2745-559e-a5fb-69cb7a536bca', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 1, 1, 'Now in the fifteenth year of the reign of Tiberius Caesar, Pontius Pilate being governor of Judea, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of the region of Ituraea and Trachonitis, and Lysanias tetrarch of Abilene,'),
  ('94337700-d13f-554d-a1f0-a86c076d6f81', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 2, 2, 'in the high priesthood of Annas and Caiaphas, the word of God came to John, the son of Zacharias, in the wilderness.'),
  ('7a8cb5e4-075c-5e10-af6e-e9bfd7eebba8', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 3, 3, 'He came into all the region around the Jordan, preaching the baptism of repentance for remission of sins.'),
  ('d785aaa2-ccee-55ea-a128-6576c0d46341', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 4, 4, 'As it is written in the book of the words of Isaiah the prophet, "The voice of one crying in the wilderness, ''Make ready the way of the Lord. Make his paths straight.'),
  ('3c0beac9-fa30-5375-a65e-74b714ed15b9', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 5, 5, 'Every valley will be filled. Every mountain and hill will be brought low. The crooked will become straight, and the rough ways smooth.'),
  ('c9f6afc3-3527-57f0-a482-c9b4b85ca713', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 6, 6, 'All flesh will see God''s salvation.''"'),
  ('511af5aa-9b86-5d11-a9bb-522a0ad854aa', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 7, 7, 'He said therefore to the multitudes who went out to be baptized by him, "You offspring of vipers, who warned you to flee from the wrath to come?'),
  ('65172ce0-b7bd-5a35-a7b0-95bb3db629fc', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 8, 8, 'Bring forth therefore fruits worthy of repentance, and don''t begin to say among yourselves, ''We have Abraham for our father;'' for I tell you that God is able to raise up children to Abraham from these stones!'),
  ('5045ea15-ffea-5ff2-a99a-5dc108fb00dd', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 9, 9, 'Even now the axe also lies at the root of the trees. Every tree therefore that doesn''t bring forth good fruit is cut down, and thrown into the fire."'),
  ('2e9d2ba9-bac0-5044-ac9d-e5241e997ff8', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 10, 10, 'The multitudes asked him, "What then must we do?"'),
  ('9a04fab2-7e81-5645-afb9-545665da70e5', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 11, 11, 'He answered them, "He who has two coats, let him give to him who has none. He who has food, let him do likewise."'),
  ('0994a7b3-957a-591f-a6ab-a6b7cf658069', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 12, 12, 'Tax collectors also came to be baptized, and they said to him, "Teacher, what must we do?"'),
  ('33ca019f-951d-5dbf-a9f2-bf10fce03a87', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 13, 13, 'He said to them, "Collect no more than that which is appointed to you."'),
  ('7d997623-bdb5-534c-a754-2075600b059e', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 14, 14, 'Soldiers also asked him, saying, "What about us? What must we do?" He said to them, "Extort from no one by violence, neither accuse anyone wrongfully. Be content with your wages."'),
  ('87739a61-96ad-54ec-a1b7-44ac46ad0a51', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 15, 15, 'As the people were in expectation, and all men reasoned in their hearts concerning John, whether perhaps he was the Christ,'),
  ('d6c58ee0-3e6f-57e2-a1d5-3982cf333dcc', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 16, 16, 'John answered them all, "I indeed baptize you with water, but he comes who is mightier than I, the latchet of whose sandals I am not worthy to loosen. He will baptize you in the Holy Spirit and fire,'),
  ('05aa9938-6055-55f5-abba-1c47b03e3058', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 17, 17, 'whose fan is in his hand, and he will thoroughly cleanse his threshing floor, and will gather the wheat into his barn; but he will burn up the chaff with unquenchable fire."'),
  ('a0b61a5c-d43e-5b72-ae67-b8f7c4c3d1c4', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 18, 18, 'Then with many other exhortations he preached good news to the people,'),
  ('1b40c80b-c2eb-5496-a018-0a00e1cb7701', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 19, 19, 'but Herod the tetrarch, being reproved by him for Herodias, his brother''s wife, and for all the evil things which Herod had done,'),
  ('34e0950e-360f-55ad-a8b5-5b6c2549cc2e', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 20, 20, 'added this also to them all, that he shut up John in prison.'),
  ('038e975b-dd43-58b4-a950-094d2a2e91e0', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 21, 21, 'Now it happened, when all the people were baptized, Jesus also had been baptized, and was praying. The sky was opened,'),
  ('1dcbe197-2e97-591b-a896-71aa89996030', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 22, 22, 'and the Holy Spirit descended in a bodily form as a dove on him; and a voice came out of the sky, saying "You are my beloved Son. In you I am well pleased."'),
  ('5e55bbf6-5bc1-5f2f-a0c7-d85019635382', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 23, 23, 'Jesus himself, when he began to teach, was about thirty years old, being the son (as was supposed) of Joseph, the son of Heli,'),
  ('01571459-90c9-58c5-a668-93d388003897', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 24, 24, 'the son of Matthat, the son of Levi, the son of Melchi, the son of Jannai, the son of Joseph,'),
  ('927181b7-e4b4-5931-a1f9-74af0b0fe87a', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 25, 25, 'the son of Mattathias, the son of Amos, the son of Nahum, the son of Esli, the son of Naggai,'),
  ('ef652f9d-cfe0-525d-ae1d-c8f3c4c4e733', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 26, 26, 'the son of Maath, the son of Mattathias, the son of Semein, the son of Joseph, the son of Judah,'),
  ('703ca7d8-5649-5b34-ada8-b9ba7f494519', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 27, 27, 'the son of Joanan, the son of Rhesa, the son of Zerubbabel, the son of Shealtiel, the son of Neri,'),
  ('f82c24b7-13fe-5ab3-ae09-b5341951c2f8', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 28, 28, 'the son of Melchi, the son of Addi, the son of Cosam, the son of Elmodam, the son of Er,'),
  ('081f55df-a322-5e8f-a141-36c54510dc16', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 29, 29, 'the son of Jose, the son of Eliezer, the son of Jorim, the son of Matthat, the son of Levi,'),
  ('04b4efbd-03ac-5d43-a0f5-0323a4e9fb06', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 30, 30, 'the son of Simeon, the son of Judah, the son of Joseph, the son of Jonan, the son of Eliakim,'),
  ('f2987e8c-01da-5fd7-a91a-1e75ceb6d64c', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 31, 31, 'the son of Melea, the son of Menan, the son of Mattatha, the son of Nathan, the son of David,'),
  ('71c1e48a-b974-54f3-a5ef-c7a481f93284', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 32, 32, 'the son of Jesse, the son of Obed, the son of Boaz, the son of Salmon, the son of Nahshon,'),
  ('9035ea67-9b98-5e21-a560-b22533eef227', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 33, 33, 'the son of Amminadab, the son of Aram, the son of Hezron, the son of Perez, the son of Judah,'),
  ('d21cb9cb-ea86-5673-ac02-ceaf825e70e8', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 34, 34, 'the son of Jacob, the son of Isaac, the son of Abraham, the son of Terah, the son of Nahor,'),
  ('e6d022f3-722f-556e-ad5f-83936638acdf', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 35, 35, 'the son of Serug, the son of Reu, the son of Peleg, the son of Eber, the son of Shelah,'),
  ('9715e4f8-f70c-5a35-a7d9-5ba136e7575b', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 36, 36, 'the son of Cainan, the son of Arphaxad, the son of Shem, the son of Noah, the son of Lamech,'),
  ('0784d3b4-7da2-5b46-a92f-7b8dbe986185', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 37, 37, 'the son of Methuselah, the son of Enoch, the son of Jared, the son of Mahalaleel, the son of Cainan,'),
  ('a8c04a97-5181-5952-ab34-f9a452b3fe7a', '28ccd734-ee6b-5cf2-aaf0-0fd0256e8f9d', NULL, 38, 38, 'the son of Enos, the son of Seth, the son of Adam, the son of God.'),
  ('8cd0170f-fb37-5a6b-ab2f-bc8d01302e3e', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 1, 1, 'Jesus, full of the Holy Spirit, returned from the Jordan, and was led by the Spirit into the wilderness'),
  ('26b702f3-b4a6-5006-a350-1d9f17f8c1f0', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 2, 2, 'for forty days, being tempted by the devil. He ate nothing in those days. Afterward, when they were completed, he was hungry.'),
  ('064f7083-d3c5-53d8-ad0a-40d4579e56ff', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 3, 3, 'The devil said to him, "If you are the Son of God, command this stone to become bread."'),
  ('544197d9-4d07-5840-a38c-9e3a94a5d883', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 4, 4, 'Jesus answered him, saying, "It is written, ''Man shall not live by bread alone, but by every word of God.''"'),
  ('5f380a18-00c0-5ab1-a3b3-1d6925bbc972', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 5, 5, 'The devil, leading him up on a high mountain, showed him all the kingdoms of the world in a moment of time.'),
  ('68ce0819-6a48-5361-abb6-96abd5889a74', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 6, 6, 'The devil said to him, "I will give you all this authority, and their glory, for it has been delivered to me; and I give it to whomever I want.'),
  ('c3fcebd0-8b96-5e98-a8fc-310beb15604d', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 7, 7, 'If you therefore will worship before me, it will all be yours."'),
  ('7bed7dd6-b532-5475-a8e0-a0b5f8160a82', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 8, 8, 'Jesus answered him, "Get behind me Satan! For it is written, ''You shall worship the Lord your God, and you shall serve him only.''"'),
  ('28aab2ce-0ec4-5bdc-a447-860d777ae496', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 9, 9, 'He led him to Jerusalem, and set him on the pinnacle of the temple, and said to him, "If you are the Son of God, cast yourself down from here,'),
  ('bf35fff9-9b0b-5217-a4af-e87263cca032', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 10, 10, 'for it is written, ''He will put his angels in charge of you, to guard you;'''),
  ('9a8843ee-2665-5bde-afe0-ee06058b3849', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 11, 11, 'and, ''On their hands they will bear you up, lest perhaps you dash your foot against a stone.''"'),
  ('a06cd6a3-c71d-50ac-ac21-9f53d4ad9468', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 12, 12, 'Jesus answering, said to him, "It has been said, ''You shall not tempt the Lord your God.''"'),
  ('af5f0e0d-49f5-535d-a5f8-8b0055b3bd62', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 13, 13, 'When the devil had completed every temptation, he departed from him until another time.'),
  ('f190ac5d-db50-5fc9-a510-c69005438bb4', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 14, 14, 'Jesus returned in the power of the Spirit into Galilee, and news about him spread through all the surrounding area.'),
  ('3d7f50e7-b849-5101-a246-9ddf8b77d09e', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 15, 15, 'He taught in their synagogues, being glorified by all.'),
  ('4864b75f-7a26-5c16-afbe-1a5795935127', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 16, 16, 'He came to Nazareth, where he had been brought up. He entered, as was his custom, into the synagogue on the Sabbath day, and stood up to read.'),
  ('90dd2cd2-5c05-56d6-a5fb-dd27ccc01c5f', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 17, 17, 'The book of the prophet Isaiah was handed to him. He opened the book, and found the place where it was written,'),
  ('51f62618-1cff-5970-af40-429603d42b08', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 18, 18, '"The Spirit of the Lord is on me, because he has anointed me to preach good news to the poor. He has sent me to heal the brokenhearted, to proclaim release to the captives, recovering of sight to the blind, to deliver those who are crushed,'),
  ('7c583bb1-3e1f-5ca4-a5f9-77e979c8e93f', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 19, 19, 'and to proclaim the acceptable year of the Lord."'),
  ('cdc1fc22-1a08-57a8-a963-904fa31d92cf', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 20, 20, 'He closed the book, gave it back to the attendant, and sat down. The eyes of all in the synagogue were fastened on him.'),
  ('2021faca-93bb-5613-abf2-8cead49a8c26', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 21, 21, 'He began to tell them, "Today, this Scripture has been fulfilled in your hearing."'),
  ('e0009c15-8b61-5320-abf3-6fb8558ab46d', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 22, 22, 'All testified about him, and wondered at the gracious words which proceeded out of his mouth, and they said, "Isn''t this Joseph''s son?"'),
  ('53c5380a-cc1e-524c-a299-955586a8a921', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 23, 23, 'He said to them, "Doubtless you will tell me this parable, ''Physician, heal yourself! Whatever we have heard done at Capernaum, do also here in your hometown.''"'),
  ('a6b83602-8127-51e0-a5e6-e25e4047ca49', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 24, 24, 'He said, "Most certainly I tell you, no prophet is acceptable in his hometown.'),
  ('ecd4c8cf-2967-5f04-a425-97ec2de9e211', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 25, 25, 'But truly I tell you, there were many widows in Israel in the days of Elijah, when the sky was shut up three years and six months, when a great famine came over all the land.'),
  ('e65cd10c-461e-59b0-a995-5c7fff1c892a', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 26, 26, 'Elijah was sent to none of them, except to Zarephath, in the land of Sidon, to a woman who was a widow.'),
  ('5a25913a-5b08-5873-a9dd-e2618fe9c2c3', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 27, 27, 'There were many lepers in Israel in the time of Elisha the prophet, yet not one of them was cleansed, except Naaman, the Syrian."'),
  ('2b6759c9-468e-547c-aeee-33efab4a8c71', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 28, 28, 'They were all filled with wrath in the synagogue, as they heard these things.'),
  ('aeb8de5b-1959-576c-aedc-959f3a50203d', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 29, 29, 'They rose up, threw him out of the city, and led him to the brow of the hill that their city was built on, that they might throw him off the cliff.'),
  ('987ddc45-fa7c-574d-a688-096869e8fa8e', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 30, 30, 'But he, passing through the midst of them, went his way.'),
  ('0dd5524b-cd66-568c-a230-f8d268b33cfb', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 31, 31, 'He came down to Capernaum, a city of Galilee. He was teaching them on the Sabbath day,'),
  ('7e7401d4-b06e-521b-a60e-d3abc0389151', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 32, 32, 'and they were astonished at his teaching, for his word was with authority.'),
  ('5bb0b9dd-940b-5ebb-aed1-e0442e684ddc', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 33, 33, 'In the synagogue there was a man who had a spirit of an unclean demon, and he cried out with a loud voice,'),
  ('c56fc7db-b5eb-58df-a662-fed451294f56', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 34, 34, 'saying, "Ah! what have we to do with you, Jesus of Nazareth? Have you come to destroy us? I know you who you are: the Holy One of God!"'),
  ('5bd3cfae-dcbc-59a4-ae67-bc7d92d8c345', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 35, 35, 'Jesus rebuked him, saying, "Be silent, and come out of him!" When the demon had thrown him down in their midst, he came out of him, having done him no harm.'),
  ('25a60382-0246-5aaa-ac74-50117853cad6', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 36, 36, 'Amazement came on all, and they spoke together, one with another, saying, "What is this word? For with authority and power he commands the unclean spirits, and they come out!"'),
  ('deee5707-240e-5662-ac4c-4bca00be59be', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 37, 37, 'News about him went out into every place of the surrounding region.'),
  ('097820eb-5018-54c2-a760-31fe164416c0', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 38, 38, 'He rose up from the synagogue, and entered into Simon''s house. Simon''s mother-in-law was afflicted with a great fever, and they begged him for her.'),
  ('5343042b-cc6c-5107-a8b3-54cf8153aa96', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 39, 39, 'He stood over her, and rebuked the fever; and it left her. Immediately she rose up and served them.'),
  ('3fa02eac-6c53-5c9c-a008-3b8937bc3b5d', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 40, 40, 'When the sun was setting, all those who had any sick with various diseases brought them to him; and he laid his hands on every one of them, and healed them.'),
  ('8128ffaf-e25c-5677-a23a-d7da5d5db83d', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 41, 41, 'Demons also came out from many, crying out, and saying, "You are the Christ, the Son of God!" Rebuking them, he didn''t allow them to speak, because they knew that he was the Christ.'),
  ('037f0f6a-d957-538d-a35a-c69c3afbef32', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 42, 42, 'When it was day, he departed and went into an uninhabited place, and the multitudes looked for him, and came to him, and held on to him, so that he wouldn''t go away from them.'),
  ('25179a13-bbc4-5498-aa6b-cfc33504aace', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 43, 43, 'But he said to them, "I must preach the good news of the Kingdom of God to the other cities also. For this reason I have been sent."'),
  ('829e93f7-361d-5e2f-a2a3-9626aa026b32', 'aa336b65-e636-50e7-ad3b-c5f6ca8448f4', NULL, 44, 44, 'He was preaching in the synagogues of Galilee.'),
  ('d846abee-7fac-5efb-adf8-2cdfd4a5791a', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 1, 1, 'Now it happened, while the multitude pressed on him and heard the word of God, that he was standing by the lake of Gennesaret.'),
  ('d5efc474-e4db-5d58-aa81-78b54614fc83', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 2, 2, 'He saw two boats standing by the lake, but the fishermen had gone out of them, and were washing their nets.'),
  ('b3579c9d-3649-5608-a8c9-d3c76240a3e9', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 3, 3, 'He entered into one of the boats, which was Simon''s, and asked him to put out a little from the land. He sat down and taught the multitudes from the boat.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e263cc63-8151-569b-ab92-cff44d7b89f4', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 4, 4, 'When he had finished speaking, he said to Simon, "Put out into the deep, and let down your nets for a catch."'),
  ('7a567435-da7e-546e-a457-b5a3e726f91d', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 5, 5, 'Simon answered him, "Master, we worked all night, and took nothing; but at your word I will let down the net."'),
  ('82e862bb-6899-5d8f-a191-c1922891a416', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 6, 6, 'When they had done this, they caught a great multitude of fish, and their net was breaking.'),
  ('60e60e1b-be8f-5bab-afb4-32b9455865af', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 7, 7, 'They beckoned to their partners in the other boat, that they should come and help them. They came, and filled both boats, so that they began to sink.'),
  ('de74e163-ac17-5f75-a2ff-5bb19dd1832e', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 8, 8, 'But Simon Peter, when he saw it, fell down at Jesus'' knees, saying, "Depart from me, for I am a sinful man, Lord."'),
  ('88ec13c0-74bf-56ad-a616-eb8d17a5701e', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 9, 9, 'For he was amazed, and all who were with him, at the catch of fish which they had caught;'),
  ('42ecc265-11e9-5c08-adcd-ab49f6cb1689', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 10, 10, 'and so also were James and John, sons of Zebedee, who were partners with Simon. Jesus said to Simon, "Don''t be afraid. From now on you will be catching people alive."'),
  ('6e758d3d-c618-517a-aeaa-00a35a4fb9e4', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 11, 11, 'When they had brought their boats to land, they left everything, and followed him.'),
  ('c7b17e6b-0e83-57ae-ae6c-522bf7eefb70', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 12, 12, 'It happened, while he was in one of the cities, behold, there was a man full of leprosy. When he saw Jesus, he fell on his face, and begged him, saying, "Lord, if you want to, you can make me clean."'),
  ('83452b71-6e93-587a-a05f-b9fa87aa6058', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 13, 13, 'He stretched out his hand, and touched him, saying, "I want to. Be made clean." Immediately the leprosy left him.'),
  ('362300ef-3d14-562e-a54f-22512dfae8a9', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 14, 14, 'He commanded him to tell no one, "But go your way, and show yourself to the priest, and offer for your cleansing according to what Moses commanded, for a testimony to them."'),
  ('e2289169-e134-5b89-a54c-4d232d4a6e45', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 15, 15, 'But the report concerning him spread much more, and great multitudes came together to hear, and to be healed by him of their infirmities.'),
  ('3fd73870-d5d2-504a-ae9a-6bc5edac094e', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 16, 16, 'But he withdrew himself into the desert, and prayed.'),
  ('2c47a6ef-d5e3-53ec-a382-326a87f2ffe5', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 17, 17, 'It happened on one of those days, that he was teaching; and there were Pharisees and teachers of the law sitting by, who had come out of every village of Galilee, Judea, and Jerusalem. The power of the Lord was with him to heal them.'),
  ('46b94ff4-2e0f-5bc6-a80a-f4902d15c74d', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 18, 18, 'Behold, men brought a paralyzed man on a cot, and they sought to bring him in to lay before Jesus.'),
  ('05564092-38c5-5458-a987-6d48af19e221', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 19, 19, 'Not finding a way to bring him in because of the multitude, they went up to the housetop, and let him down through the tiles with his cot into the midst before Jesus.'),
  ('c06a1532-ad54-5af6-a016-1d82764c0a4b', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 20, 20, 'Seeing their faith, he said to him, "Man, your sins are forgiven you."'),
  ('b022856e-963a-55db-af9f-457a22c1cff4', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 21, 21, 'The scribes and the Pharisees began to reason, saying, "Who is this that speaks blasphemies? Who can forgive sins, but God alone?"'),
  ('dde0a24f-3873-5ab4-afba-4ce8db502649', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 22, 22, 'But Jesus, perceiving their thoughts, answered them, "Why are you reasoning so in your hearts?'),
  ('2f797774-355a-5cd6-af39-ccf1c86cafba', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 23, 23, 'Which is easier to say, ''Your sins are forgiven you;'' or to say, ''Arise and walk?'''),
  ('1e802d1d-6604-56d2-af61-3463e2f8d314', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 24, 24, 'But that you may know that the Son of Man has authority on earth to forgive sins" (he said to the paralyzed man), "I tell you, arise, and take up your cot, and go to your house."'),
  ('ac72c45f-e9f3-5efc-ab93-e24ae19df2e7', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 25, 25, 'Immediately he rose up before them, and took up that which he was laying on, and departed to his house, glorifying God.'),
  ('ac60da17-5d49-5f1e-ac74-f62206db0c04', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 26, 26, 'Amazement took hold on all, and they glorified God. They were filled with fear, saying, "We have seen strange things today."'),
  ('4326dcb4-a413-5ec1-a0fa-15d6bba08d76', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 27, 27, 'After these things he went out, and saw a tax collector named Levi sitting at the tax office, and said to him, "Follow me!"'),
  ('00e4b263-42ba-514a-a450-2c09f21f1eb7', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 28, 28, 'He left everything, and rose up and followed him.'),
  ('289378e9-ad3a-5c8b-af0c-025d11c64587', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 29, 29, 'Levi made a great feast for him in his house. There was a great crowd of tax collectors and others who were reclining with them.'),
  ('afaa6b9f-b24c-5b0b-a699-7687cfa0ac64', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 30, 30, 'Their scribes and the Pharisees murmured against his disciples, saying, "Why do you eat and drink with the tax collectors and sinners?"'),
  ('6a9b063c-d71e-584f-a236-6d7953c98dea', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 31, 31, 'Jesus answered them, "Those who are healthy have no need for a physician, but those who are sick do.'),
  ('25951b6c-4fb4-595b-ace8-16324df0fb44', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 32, 32, 'I have not come to call the righteous, but sinners to repentance."'),
  ('cf89ffed-804b-5517-a62c-7adb95a216ce', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 33, 33, 'They said to him, "Why do John''s disciples often fast and pray, likewise also the disciples of the Pharisees, but yours eat and drink?"'),
  ('a87be8a9-8b6c-5d81-afad-7c263c4d928d', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 34, 34, 'He said to them, "Can you make the friends of the bridegroom fast, while the bridegroom is with them?'),
  ('1ce80a35-8a7f-5a30-ad95-c8975d286c5f', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 35, 35, 'But the days will come when the bridegroom will be taken away from them. Then they will fast in those days."'),
  ('637868e1-4ce3-5e97-afbd-53e219d6ea2a', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 36, 36, 'He also told a parable to them. "No one puts a piece from a new garment on an old garment, or else he will tear the new, and also the piece from the new will not match the old.'),
  ('f5442463-6264-53ec-adbd-ee5586664aaa', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 37, 37, 'No one puts new wine into old wineskins, or else the new wine will burst the skins, and it will be spilled, and the skins will be destroyed.'),
  ('6d2d67f4-b212-5c17-af63-d37eb035aee0', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 38, 38, 'But new wine must be put into fresh wineskins, and both are preserved.'),
  ('731bb65f-63c9-5736-a9bd-90ee3f305767', 'c5b30219-b4fc-5b1e-ae0d-e4b248ed1809', NULL, 39, 39, 'No man having drunk old wine immediately desires new, for he says, ''The old is better.''"'),
  ('952ecec5-1d18-53b4-aa7b-38efb65247c1', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 1, 1, 'Now it happened on the second Sabbath after the first, that he was going through the grain fields. His disciples plucked the heads of grain, and ate, rubbing them in their hands.'),
  ('de9352f7-5477-5b6e-a78e-8144c8b5189f', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 2, 2, 'But some of the Pharisees said to them, "Why do you do that which is not lawful to do on the Sabbath day?"'),
  ('bbe9e929-7f26-535e-ade6-a145753ca411', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 3, 3, 'Jesus, answering them, said, "Haven''t you read what David did when he was hungry, he, and those who were with him;'),
  ('5d056bd9-2612-5946-a429-8ef76c6f99e6', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 4, 4, 'how he entered into the house of God, and took and ate the show bread, and gave also to those who were with him, which is not lawful to eat except for the priests alone?"'),
  ('78959459-ee85-5720-a976-c1f7815b5b38', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 5, 5, 'He said to them, "The Son of Man is lord of the Sabbath."'),
  ('b260d539-8ddf-5361-a5bb-f36a730ff25f', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 6, 6, 'It also happened on another Sabbath that he entered into the synagogue and taught. There was a man there, and his right hand was withered.'),
  ('7a7fbb93-e018-590c-a7b8-c60656531c68', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 7, 7, 'The scribes and the Pharisees watched him, to see whether he would heal on the Sabbath, that they might find an accusation against him.'),
  ('c54f6080-0f4c-52ca-a3a4-d9d74180a22e', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 8, 8, 'But he knew their thoughts; and he said to the man who had the withered hand, "Rise up, and stand in the middle." He arose and stood.'),
  ('22646b0c-b989-542d-ab46-cffedf50aac3', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 9, 9, 'Then Jesus said to them, "I will ask you something: Is it lawful on the Sabbath to do good, or to do harm? To save a life, or to kill?"'),
  ('cc19807d-28c1-5e06-adc2-9a61b56cfc00', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 10, 10, 'He looked around at them all, and said to the man, "Stretch out your hand." He did, and his hand was restored as sound as the other.'),
  ('bbc97e7f-506c-5831-a659-7f45884fa670', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 11, 11, 'But they were filled with rage, and talked with one another about what they might do to Jesus.'),
  ('c8aabae4-c3b3-5119-a461-044160336ee8', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 12, 12, 'It happened in these days, that he went out to the mountain to pray, and he continued all night in prayer to God.'),
  ('9f104b77-6be6-504c-ac52-7200c9d716c4', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 13, 13, 'When it was day, he called his disciples, and from them he chose twelve, whom he also named apostles:'),
  ('e64b2bec-ab54-5766-af6a-3e7b36c44ed6', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 14, 14, 'Simon, whom he also named Peter; Andrew, his brother; James; John; Philip; Bartholomew;'),
  ('eeaccb61-9fca-5200-a5d6-4b66294b7297', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 15, 15, 'Matthew; Thomas; James, the son of Alphaeus; Simon, who was called the Zealot;'),
  ('f1415dc7-c939-5c21-a0ab-08ed35100cd0', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 16, 16, 'Judas the son of James; and Judas Iscariot, who also became a traitor.'),
  ('4cd84b74-b761-546c-a58a-facc476c1c4e', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 17, 17, 'He came down with them, and stood on a level place, with a crowd of his disciples, and a great number of the people from all Judea and Jerusalem, and the sea coast of Tyre and Sidon, who came to hear him and to be healed of their diseases;'),
  ('c042d9df-8a16-5dc1-a8f6-45f3309985c8', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 18, 18, 'as well as those who were troubled by unclean spirits, and they were being healed.'),
  ('5c198292-8c63-5454-a22d-e1e4580654ea', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 19, 19, 'All the multitude sought to touch him, for power came out from him and healed them all.'),
  ('b035fd9b-6ca6-534b-a25a-e2e7a10e3da1', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 20, 20, 'He lifted up his eyes to his disciples, and said, "Blessed are you who are poor, for yours is the Kingdom of God.'),
  ('c392a8a7-8873-560b-a546-708c6235f980', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 21, 21, 'Blessed are you who hunger now, for you will be filled. Blessed are you who weep now, for you will laugh.'),
  ('087e153e-3c46-5f02-a152-5858c6a5bf46', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 22, 22, 'Blessed are you when men shall hate you, and when they shall exclude and mock you, and throw out your name as evil, for the Son of Man''s sake.'),
  ('10dbdf12-6f7c-5751-a716-2f47591c6bf1', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 23, 23, 'Rejoice in that day, and leap for joy, for behold, your reward is great in heaven, for their fathers did the same thing to the prophets.'),
  ('094d9c21-e8c2-5954-ae04-572f2773ba7b', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 24, 24, '"But woe to you who are rich! For you have received your consolation.'),
  ('ecf2eaf7-0844-54a4-abea-430fa58af5d6', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 25, 25, 'Woe to you, you who are full now, for you will be hungry. Woe to you who laugh now, for you will mourn and weep.'),
  ('07736aa6-6f54-5880-a9d1-37f463810c8e', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 26, 26, 'Woe, when men speak well of you, for their fathers did the same thing to the false prophets.'),
  ('381958ae-34b3-5f1b-a61a-df4642d3ae38', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 27, 27, '"But I tell you who hear: love your enemies, do good to those who hate you,'),
  ('ef095b83-a395-579b-acbd-1aa6bf0b7aaf', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 28, 28, 'bless those who curse you, and pray for those who mistreat you.'),
  ('0bc20822-b9b3-5a08-a1c0-2bd5bf73cfe7', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 29, 29, 'To him who strikes you on the cheek, offer also the other; and from him who takes away your cloak, don''t withhold your coat also.'),
  ('9526bbdc-d957-5810-a100-35b9c8f7d17b', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 30, 30, 'Give to everyone who asks you, and don''t ask him who takes away your goods to give them back again.'),
  ('44babf38-1555-599a-a5bd-15da4ebd613a', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 31, 31, '"As you would like people to do to you, do exactly so to them.'),
  ('e3ed17f3-085a-5f03-aca9-37c61592943f', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 32, 32, 'If you love those who love you, what credit is that to you? For even sinners love those who love them.'),
  ('93f6b33f-03d3-5529-a0e7-f12b658f1379', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 33, 33, 'If you do good to those who do good to you, what credit is that to you? For even sinners do the same.'),
  ('647a83af-40cf-5cdb-a6d9-49db83ae160b', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 34, 34, 'If you lend to those from whom you hope to receive, what credit is that to you? Even sinners lend to sinners, to receive back as much.'),
  ('ea38b198-de6f-5ffd-a015-4686e59f5247', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 35, 35, 'But love your enemies, and do good, and lend, expecting nothing back; and your reward will be great, and you will be children of the Most High; for he is kind toward the unthankful and evil.'),
  ('586b7253-2cb2-5f6a-a3b1-f622bb5427c5', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 36, 36, 'Therefore be merciful, even as your Father is also merciful.'),
  ('2e2f8ef1-9118-57ff-aa92-33217f956bc2', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 37, 37, 'Don''t judge, and you won''t be judged. Don''t condemn, and you won''t be condemned. Set free, and you will be set free.'),
  ('a40bcfc4-251f-5cc7-a18d-fbd043a12f64', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 38, 38, '"Give, and it will be given to you: good measure, pressed down, shaken together, and running over, will be given to you. For with the same measure you measure it will be measured back to you."'),
  ('0b215ef3-922c-558b-aa6d-34dfcb48fd5a', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 39, 39, 'He spoke a parable to them. "Can the blind guide the blind? Won''t they both fall into a pit?'),
  ('91161822-83be-56bf-a92c-2e6024193119', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 40, 40, 'A disciple is not above his teacher, but everyone when he is fully trained will be like his teacher.'),
  ('43b16e68-6069-5ca1-a2c3-8cf616995b06', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 41, 41, 'Why do you see the speck of chaff that is in your brother''s eye, but don''t consider the beam that is in your own eye?'),
  ('440dd244-0490-576d-a22f-d66f55bdc586', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 42, 42, 'Or how can you tell your brother, ''Brother, let me remove the speck of chaff that is in your eye,'' when you yourself don''t see the beam that is in your own eye? You hypocrite! First remove the beam from your own eye, and then you can see clearly to remove the speck of chaff that is in your brother''s eye.'),
  ('2f2602f7-e16e-5d79-ae68-7c9b3993c41f', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 43, 43, 'For there is no good tree that brings forth rotten fruit; nor again a rotten tree that brings forth good fruit.'),
  ('773282a2-12ca-539b-a0c7-cc844a2135fb', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 44, 44, 'For each tree is known by its own fruit. For people don''t gather figs from thorns, nor do they gather grapes from a bramble bush.'),
  ('da632e6c-660b-5b34-a23a-16f4f28f6cd1', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 45, 45, 'The good man out of the good treasure of his heart brings out that which is good, and the evil man out of the evil treasure of his heart brings out that which is evil, for out of the abundance of the heart, his mouth speaks.'),
  ('996051e7-99fd-5812-af07-ddfe7d2767d8', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 46, 46, '"Why do you call me, ''Lord, Lord,'' and don''t do the things which I say?'),
  ('ec6db8dc-9ad8-5405-a1de-2a729389324f', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 47, 47, 'Everyone who comes to me, and hears my words, and does them, I will show you who he is like.'),
  ('082f489c-48b3-545e-a845-f702035ba71a', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 48, 48, 'He is like a man building a house, who dug and went deep, and laid a foundation on the rock. When a flood arose, the stream broke against that house, and could not shake it, because it was founded on the rock.'),
  ('cc311b76-1ed3-589e-a3e4-2373af2d81ef', '04d338a1-86e6-5351-ad35-110f8783ca0d', NULL, 49, 49, 'But he who hears, and doesn''t do, is like a man who built a house on the earth without a foundation, against which the stream broke, and immediately it fell, and the ruin of that house was great."'),
  ('bbc9c63a-de79-5479-a729-59670e87e743', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 1, 1, 'After he had finished speaking in the hearing of the people, he entered into Capernaum.'),
  ('311505b3-647b-520d-a85b-ba101b292270', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 2, 2, 'A certain centurion''s servant, who was dear to him, was sick and at the point of death.'),
  ('53e190bd-40b7-58cc-a3da-04d5019300e1', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 3, 3, 'When he heard about Jesus, he sent to him elders of the Jews, asking him to come and save his servant.'),
  ('c1c125d8-93d7-556a-aa5c-951afea8818a', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 4, 4, 'When they came to Jesus, they begged him earnestly, saying, "He is worthy for you to do this for him,'),
  ('718384a3-105c-570e-a042-f85f71d86be4', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 5, 5, 'for he loves our nation, and he built our synagogue for us."'),
  ('efca44f0-cf06-582e-ab92-8e0550da1125', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 6, 6, 'Jesus went with them. When he was now not far from the house, the centurion sent friends to him, saying to him, "Lord, don''t trouble yourself, for I am not worthy for you to come under my roof.'),
  ('ce145a4a-ce68-549a-ae25-31ef0e8da3ca', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 7, 7, 'Therefore I didn''t even think myself worthy to come to you; but say the word, and my servant will be healed.'),
  ('f116cfe8-0f44-5d41-a130-4bcc195f263f', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 8, 8, 'For I also am a man placed under authority, having under myself soldiers. I tell this one, ''Go!'' and he goes; and to another, ''Come!'' and he comes; and to my servant, ''Do this,'' and he does it."'),
  ('14bff853-5f17-59f1-a9b1-90820657460f', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 9, 9, 'When Jesus heard these things, he marveled at him, and turned and said to the multitude who followed him, "I tell you, I have not found such great faith, no, not in Israel."'),
  ('006e9883-85e2-575d-a8ba-f4a6bb8d8f78', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 10, 10, 'Those who were sent, returning to the house, found that the servant who had been sick was well.'),
  ('657b4716-a161-55ea-ac17-bdca2879af50', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 11, 11, 'It happened soon afterwards, that he went to a city called Nain. Many of his disciples, along with a great multitude, went with him.'),
  ('7e231580-73e0-5b3f-af02-9f8a74a5b62f', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 12, 12, 'Now when he drew near to the gate of the city, behold, one who was dead was carried out, the only son of his mother, and she was a widow. Many people of the city were with her.'),
  ('4b5271ac-b3ce-51e5-ad84-433c63f19972', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 13, 13, 'When the Lord saw her, he had compassion on her, and said to her, "Don''t cry."'),
  ('b2cb3f60-1af6-54be-af7c-719dec633fdb', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 14, 14, 'He came near and touched the coffin, and the bearers stood still. He said, "Young man, I tell you, arise!"'),
  ('9c8fb2f3-5b76-5bc4-aebb-e160d20ea4e4', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 15, 15, 'He who was dead sat up, and began to speak. And he gave him to his mother.'),
  ('567a0757-4b40-59bd-afff-d24ae8a5252b', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 16, 16, 'Fear took hold of all, and they glorified God, saying, "A great prophet has arisen among us!" and, "God has visited his people!"'),
  ('47ed532a-9ae6-5508-a142-2fbee08c33fa', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 17, 17, 'This report went out concerning him in the whole of Judea, and in all the surrounding region.'),
  ('309c5c06-bfdd-54fd-a835-cf862bb85b24', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 18, 18, 'The disciples of John told him about all these things.'),
  ('194c0963-b392-5893-a209-37471cc43c10', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 19, 19, 'John, calling to himself two of his disciples, sent them to Jesus, saying, "Are you the one who is coming, or should we look for another?"'),
  ('6fac28a2-7696-58f9-a037-80d434ea931b', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 20, 20, 'When the men had come to him, they said, "John the Baptizer has sent us to you, saying, ''Are you he who comes, or should we look for another?''"'),
  ('0a556391-b3b9-5cb2-ad44-b0271bb0e7e8', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 21, 21, 'In that hour he cured many of diseases and plagues and evil spirits; and to many who were blind he gave sight.'),
  ('f4fec227-422e-501d-a988-92fe319037d8', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 22, 22, 'Jesus answered them, "Go and tell John the things which you have seen and heard: that the blind receive their sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised up, and the poor have good news preached to them.'),
  ('5b70ba59-344e-5c0c-abdc-28db093567ec', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 23, 23, 'Blessed is he who is not offended by me."'),
  ('4be23281-6d40-57ba-ab44-172abcf543ea', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 24, 24, 'When John''s messengers had departed, he began to tell the multitudes about John, "What did you go out into the wilderness to see? A reed shaken by the wind?'),
  ('11e5d224-ff52-5b40-a2dd-4e4eec7689c4', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 25, 25, 'But what did you go out to see? A man clothed in soft clothing? Behold, those who are gorgeously dressed, and live delicately, are in kings'' courts.'),
  ('5a4b2c21-7884-5a46-ac70-fb48c8d93cb1', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 26, 26, 'But what did you go out to see? A prophet? Yes, I tell you, and much more than a prophet.'),
  ('237d3a0b-9420-5c7b-a53e-48e1b728e219', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 27, 27, 'This is he of whom it is written, ''Behold, I send my messenger before your face, who will prepare your way before you.'''),
  ('38de1709-03e6-5d09-a851-657504414d59', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 28, 28, '"For I tell you, among those who are born of women there is not a greater prophet than John the Baptizer, yet he who is least in the Kingdom of God is greater than he."'),
  ('691b6fa6-d538-54d5-aae4-47fc83a11c1e', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 29, 29, 'When all the people and the tax collectors heard this, they declared God to be just, having been baptized with John''s baptism.'),
  ('1ae42f04-8b95-5e71-ad14-4410aaf6c17d', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 30, 30, 'But the Pharisees and the lawyers rejected the counsel of God, not being baptized by him themselves.'),
  ('eeee34f3-3760-50fb-a045-3939dad68278', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 31, 31, '"To what then will I liken the people of this generation? What are they like?'),
  ('ef62237f-835c-5185-ad43-b2d8287bd0b1', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 32, 32, 'They are like children who sit in the marketplace, and call one to another, saying, ''We piped to you, and you didn''t dance. We mourned, and you didn''t weep.'''),
  ('9159bf9c-57d0-57f2-a235-7031f1204c33', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 33, 33, 'For John the Baptizer came neither eating bread nor drinking wine, and you say, ''He has a demon.'''),
  ('7ad8ff7b-5ce8-56a9-a2d8-7f4e40f6de1e', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 34, 34, 'The Son of Man has come eating and drinking, and you say, ''Behold, a gluttonous man, and a drunkard; a friend of tax collectors and sinners!'''),
  ('82864bd1-b575-5063-ac82-6aff25588e26', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 35, 35, 'Wisdom is justified by all her children."'),
  ('9024ce54-31d2-5bc9-a7a5-ef9e9f508a65', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 36, 36, 'One of the Pharisees invited him to eat with him. He entered into the Pharisee''s house, and sat at the table.'),
  ('a41f9035-e53f-5896-ad9c-42bbed8e8ac6', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 37, 37, 'Behold, a woman in the city who was a sinner, when she knew that he was reclining in the Pharisee''s house, she brought an alabaster jar of ointment.'),
  ('9214a2e2-656e-57ef-aff0-3a53de427c81', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 38, 38, 'Standing behind at his feet weeping, she began to wet his feet with her tears, and she wiped them with the hair of her head, kissed his feet, and anointed them with the ointment.'),
  ('4337b1b2-76e8-58f9-a0b4-df8a14389cbb', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 39, 39, 'Now when the Pharisee who had invited him saw it, he said to himself, "This man, if he were a prophet, would have perceived who and what kind of woman this is who touches him, that she is a sinner."'),
  ('b7ec6eda-bdd2-5974-ac7e-b00c5ce2856d', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 40, 40, 'Jesus answered him, "Simon, I have something to tell you." He said, "Teacher, say on."'),
  ('9d2d7e93-8e1c-53f1-a8a3-dc1a6be9e67f', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 41, 41, '"A certain lender had two debtors. The one owed five hundred denarii, and the other fifty.'),
  ('610ab9f3-4f5c-5c49-ac50-63a9d557e296', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 42, 42, 'When they couldn''t pay, he forgave them both. Which of them therefore will love him most?"'),
  ('b0c3d1f1-5576-558f-ab4d-310313407d9e', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 43, 43, 'Simon answered, "He, I suppose, to whom he forgave the most." He said to him, "You have judged correctly."'),
  ('7aa0492d-143a-5333-a7d1-3fe234fb3595', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 44, 44, 'Turning to the woman, he said to Simon, "Do you see this woman? I entered into your house, and you gave me no water for my feet, but she has wet my feet with her tears, and wiped them with the hair of her head.'),
  ('d89e3939-ba78-5abb-a6b1-fb97d4c4a8dd', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 45, 45, 'You gave me no kiss, but she, since the time I came in, has not ceased to kiss my feet.'),
  ('fa29d3c3-6ef6-5cc6-acb9-26caa0e374c3', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 46, 46, 'You didn''t anoint my head with oil, but she has anointed my feet with ointment.'),
  ('2ab699e6-e385-5e2d-a5cc-87959633e2ef', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 47, 47, 'Therefore I tell you, her sins, which are many, are forgiven, for she loved much. But to whom little is forgiven, the same loves little."'),
  ('bf579869-6233-5f23-a04e-79053f6c933e', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 48, 48, 'He said to her, "Your sins are forgiven."'),
  ('dfe70a82-e5b5-5294-a563-e2a5059ffb3c', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 49, 49, 'Those who sat at the table with him began to say to themselves, "Who is this who even forgives sins?"'),
  ('e96cc52d-bca1-5c37-a0a7-e336acac900a', 'e3eb9e7b-70bb-5549-a2a5-b2383d4fe07c', NULL, 50, 50, 'He said to the woman, "Your faith has saved you. Go in peace."'),
  ('0dc8700a-6f1f-5086-adc7-4aafea55654a', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 1, 1, 'It happened soon afterwards, that he went about through cities and villages, preaching and bringing the good news of the Kingdom of God. With him were the twelve,'),
  ('dad75973-11f7-574b-a713-a13eceb3cc68', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 2, 2, 'and certain women who had been healed of evil spirits and infirmities: Mary who was called Magdalene, from whom seven demons had gone out;'),
  ('6b089cb7-c311-5773-a67b-4e4d32ca96c1', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 3, 3, 'and Joanna, the wife of Chuzas, Herod''s steward; Susanna; and many others; who served them from their possessions.'),
  ('68011dd6-d2ab-5b12-aea5-7adffaad1276', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 4, 4, 'When a great multitude came together, and people from every city were coming to him, he spoke by a parable.'),
  ('5a839df5-258d-5985-a35a-6c556544b5f7', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 5, 5, '"The farmer went out to sow his seed. As he sowed, some fell along the road, and it was trampled under foot, and the birds of the sky devoured it.'),
  ('92efad0c-355f-5ab4-a6fe-1b184ee0fe00', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 6, 6, 'Other seed fell on the rock, and as soon as it grew, it withered away, because it had no moisture.'),
  ('896c8edb-3c39-55cc-a37f-7d20bcea2b35', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 7, 7, 'Other fell amid the thorns, and the thorns grew with it, and choked it.'),
  ('b2c480fd-d732-58ba-a692-5112b90f89f7', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 8, 8, 'Other fell into the good ground, and grew, and brought forth fruit one hundred times." As he said these things, he called out, "He who has ears to hear, let him hear!"'),
  ('45fa3247-9427-5d9b-a575-db949c1a1c42', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 9, 9, 'Then his disciples asked him, "What does this parable mean?"'),
  ('26621cc4-b028-5d6b-a00b-5a8d2bde9503', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 10, 10, 'He said, "To you it is given to know the mysteries of the Kingdom of God, but to the rest in parables; that ''seeing they may not see, and hearing they may not understand.'''),
  ('4e293001-4484-55bd-a9cc-1fd448850749', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 11, 11, 'Now the parable is this: The seed is the word of God.'),
  ('22f551cf-c37c-54d8-a229-2d85c0824497', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 12, 12, 'Those along the road are those who hear, then the devil comes, and takes away the word from their heart, that they may not believe and be saved.'),
  ('9f0c3562-d00c-5147-af03-01cb32eaebe6', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 13, 13, 'Those on the rock are they who, when they hear, receive the word with joy; but these have no root, who believe for a while, then fall away in time of temptation.'),
  ('db25acb6-c290-5a35-a16e-dc49f9143e1b', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 14, 14, 'That which fell among the thorns, these are those who have heard, and as they go on their way they are choked with cares, riches, and pleasures of life, and bring no fruit to maturity.'),
  ('f4ea8925-510a-510d-a174-1cff3a3747f6', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 15, 15, 'That in the good ground, these are such as in an honest and good heart, having heard the word, hold it tightly, and bring forth fruit with patience.'),
  ('9ae6bfd8-5635-5a85-aa74-4acd2e5399fd', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 16, 16, '"No one, when he has lit a lamp, covers it with a container, or puts it under a bed; but puts it on a stand, that those who enter in may see the light.'),
  ('7b737eae-feb8-57b3-a458-a43fd4809ffa', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 17, 17, 'For nothing is hidden, that will not be revealed; nor anything secret, that will not be known and come to light.'),
  ('83d0e233-0a55-5579-aa5f-623c452c1a3a', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 18, 18, 'Be careful therefore how you hear. For whoever has, to him will be given; and whoever doesn''t have, from him will be taken away even that which he thinks he has."'),
  ('10474142-8313-585a-a8dc-8ca379e03294', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 19, 19, 'His mother and brothers came to him, and they could not come near him for the crowd.'),
  ('72a984c0-b290-5e8e-a53b-a044461c7692', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 20, 20, 'It was told him by some saying, "Your mother and your brothers stand outside, desiring to see you."'),
  ('b83ecc8a-22bb-551b-a951-b567898f1056', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 21, 21, 'But he answered them, "My mother and my brothers are these who hear the word of God, and do it."'),
  ('8aba8612-4981-5f76-a1eb-7d327d054bb7', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 22, 22, 'Now it happened on one of those days, that he entered into a boat, himself and his disciples, and he said to them, "Let''s go over to the other side of the lake." So they launched out.'),
  ('cd8f1325-7b37-50f4-a1ee-de1e3826bf3a', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 23, 23, 'But as they sailed, he fell asleep. A wind storm came down on the lake, and they were taking on dangerous amounts of water.'),
  ('e669f185-5641-59a4-ad1e-b0e941662844', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 24, 24, 'They came to him, and awoke him, saying, "Master, master, we are dying!" He awoke, and rebuked the wind and the raging of the water, and they ceased, and it was calm.'),
  ('a848ad2b-0a38-5a18-a560-e3a2318c1964', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 25, 25, 'He said to them, "Where is your faith?" Being afraid they marveled, saying one to another, "Who is this, then, that he commands even the winds and the water, and they obey him?"'),
  ('3fdd3946-13ae-52d6-a21d-2c0b4cb45043', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 26, 26, 'They arrived at the country of the Gadarenes, which is opposite Galilee.'),
  ('3850b127-b5df-529d-ab1f-f244a472b9ae', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 27, 27, 'When Jesus stepped ashore, a certain man out of the city who had demons for a long time met him. He wore no clothes, and didn''t live in a house, but in the tombs.'),
  ('70ab8295-b762-5831-adb4-59733119bf5f', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 28, 28, 'When he saw Jesus, he cried out, and fell down before him, and with a loud voice said, "What do I have to do with you, Jesus, you Son of the Most High God? I beg you, don''t torment me!"'),
  ('bdd289a1-1d3f-526b-a048-0c279f9a9773', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 29, 29, 'For Jesus was commanding the unclean spirit to come out of the man. For the unclean spirit had often seized the man. He was kept under guard, and bound with chains and fetters. Breaking the bands apart, he was driven by the demon into the desert.'),
  ('58ece731-2cf1-545a-a859-52284aed7f6e', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 30, 30, 'Jesus asked him, "What is your name?" He said, "Legion," for many demons had entered into him.'),
  ('e755313a-1562-5649-a11e-a84de266cb4b', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 31, 31, 'They begged him that he would not command them to go into the abyss.'),
  ('881dcb34-ceff-51b7-a8d1-422c4e6bfdeb', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 32, 32, 'Now there was there a herd of many pigs feeding on the mountain, and they begged him that he would allow them to enter into those. He allowed them.'),
  ('b379c693-360a-5206-aef1-0e80cb477883', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 33, 33, 'The demons came out from the man, and entered into the pigs, and the herd rushed down the steep bank into the lake, and were drowned.'),
  ('ec04460c-a2d3-5049-a101-52a3bcdf64f6', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 34, 34, 'When those who fed them saw what had happened, they fled, and told it in the city and in the country.'),
  ('9bff5367-a793-5aa1-af23-550b9af62157', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 35, 35, 'People went out to see what had happened. They came to Jesus, and found the man from whom the demons had gone out, sitting at Jesus'' feet, clothed and in his right mind; and they were afraid.'),
  ('5f50b2d2-b7dd-5e0a-a02a-3b83117f7aaa', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 36, 36, 'Those who saw it told them how he who had been possessed by demons was healed.'),
  ('6769db78-97de-508f-ace2-ec79ac0608dd', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 37, 37, 'All the people of the surrounding country of the Gadarenes asked him to depart from them, for they were very much afraid. He entered into the boat, and returned.'),
  ('aa18e7c6-cd58-5438-af5d-cd2586922b8d', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 38, 38, 'But the man from whom the demons had gone out begged him that he might go with him, but Jesus sent him away, saying,'),
  ('31577934-7095-5b30-a52c-9e501c33f329', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 39, 39, '"Return to your house, and declare what great things God has done for you." He went his way, proclaiming throughout the whole city what great things Jesus had done for him.'),
  ('68bf2bfe-f2dc-5de4-a4e0-1e0797d7cb32', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 40, 40, 'It happened, when Jesus returned, that the multitude welcomed him, for they were all waiting for him.'),
  ('acd98efc-9b49-5413-a149-317e5db78be0', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 41, 41, 'Behold, there came a man named Jairus, and he was a ruler of the synagogue. He fell down at Jesus'' feet, and begged him to come into his house,'),
  ('663b02cf-5bc7-5539-a25d-9f8e37801dae', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 42, 42, 'for he had an only daughter, about twelve years of age, and she was dying. But as he went, the multitudes pressed against him.'),
  ('90182261-63f0-51c6-a75e-99d7e7937695', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 43, 43, 'A woman who had a flow of blood for twelve years, who had spent all her living on physicians, and could not be healed by any,'),
  ('8f1c360c-4f3a-5256-a0d0-924e4e8e655b', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 44, 44, 'came behind him, and touched the fringe of his cloak, and immediately the flow of her blood stopped.'),
  ('5459156d-faea-5838-af2a-1f1c80aa4edd', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 45, 45, 'Jesus said, "Who touched me?" When all denied it, Peter and those with him said, "Master, the multitudes press and jostle you, and you say, ''Who touched me?''"'),
  ('c295db08-04d8-58e4-a476-54f772efbeb2', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 46, 46, 'But Jesus said, "Someone did touch me, for I perceived that power has gone out of me."'),
  ('9537752a-6c39-5cc1-ad74-2d82b763a1e6', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 47, 47, 'When the woman saw that she was not hidden, she came trembling, and falling down before him declared to him in the presence of all the people the reason why she had touched him, and how she was healed immediately.'),
  ('7efcb4f9-54df-5e36-a39d-4f87f963efb4', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 48, 48, 'He said to her, "Daughter, cheer up. Your faith has made you well. Go in peace."'),
  ('d5a10e58-c698-5d98-a074-502edce511ba', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 49, 49, 'While he still spoke, one from the ruler of the synagogue''s house came, saying to him, "Your daughter is dead. Don''t trouble the Teacher."'),
  ('a1fa784c-21c5-5aeb-acc5-146e286730ae', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 50, 50, 'But Jesus hearing it, answered him, "Don''t be afraid. Only believe, and she will be healed."'),
  ('c5c0b2f4-2b66-5dd1-ad86-d088e8c0a634', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 51, 51, 'When he came to the house, he didn''t allow anyone to enter in, except Peter, John, James, the father of the child, and her mother.'),
  ('1a0e1711-68fd-5d61-a9ab-00d65a163d6b', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 52, 52, 'All were weeping and mourning her, but he said, "Don''t weep. She isn''t dead, but sleeping."'),
  ('f0dc2883-3872-59c8-a53e-553babd8465e', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 53, 53, 'They were ridiculing him, knowing that she was dead.'),
  ('37f593ab-f2c2-574d-a2e6-4ce1701dd183', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 54, 54, 'But he put them all outside, and taking her by the hand, he called, saying, "Child, arise!"'),
  ('df165318-09b4-5d9b-af11-22f248279323', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 55, 55, 'Her spirit returned, and she rose up immediately. He commanded that something be given to her to eat.'),
  ('db591b11-9eb9-538a-a268-d9c35381d97e', '49b59930-2ae5-5286-a9c4-edb7cb489263', NULL, 56, 56, 'Her parents were amazed, but he commanded them to tell no one what had been done.'),
  ('e4550230-f083-5a2e-a002-5e0b687a7501', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 1, 1, 'He called the twelve together, and gave them power and authority over all demons, and to cure diseases.'),
  ('f04ca768-4587-56e4-a83b-aef47146a6fb', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 2, 2, 'He sent them forth to preach the Kingdom of God, and to heal the sick.'),
  ('dd9e6693-2977-5d7b-a6c6-063ea78e3dae', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 3, 3, 'He said to them, "Take nothing for your journey--neither staffs, nor wallet, nor bread, nor money; neither have two coats apiece.'),
  ('365c19bf-0403-5514-a282-14fe5e3680ba', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 4, 4, 'Into whatever house you enter, stay there, and depart from there.'),
  ('8f751661-f6ee-59d2-a371-a69689bc17e3', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 5, 5, 'As many as don''t receive you, when you depart from that city, shake off even the dust from your feet for a testimony against them."'),
  ('c521c687-f1b7-5a38-ad66-f665bb4c6b6f', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 6, 6, 'They departed, and went throughout the villages, preaching the Good News, and healing everywhere.'),
  ('130a8f41-fc86-5bdf-ac6b-26c2486ccd77', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 7, 7, 'Now Herod the tetrarch heard of all that was done by him; and he was very perplexed, because it was said by some that John had risen from the dead,'),
  ('793c1925-d4f1-51c2-adb3-04b8121e034c', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 8, 8, 'and by some that Elijah had appeared, and by others that one of the old prophets had risen again.'),
  ('2eacf865-48ba-5fca-a8f5-e0addf57657e', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 9, 9, 'Herod said, "John I beheaded, but who is this, about whom I hear such things?" He sought to see him.'),
  ('2de09ca6-c32b-5b14-adf5-ee7254b77d5b', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 10, 10, 'The apostles, when they had returned, told him what things they had done. He took them, and withdrew apart to a deserted place of a city called Bethsaida.'),
  ('e93430ec-c1a8-5858-a765-5cb57644eb69', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 11, 11, 'But the multitudes, perceiving it, followed him. He welcomed them, and spoke to them of the Kingdom of God, and he cured those who needed healing.'),
  ('ec529ace-47cb-5687-adfb-3241f590e9ad', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 12, 12, 'The day began to wear away; and the twelve came, and said to him, "Send the multitude away, that they may go into the surrounding villages and farms, and lodge, and get food, for we are here in a deserted place."'),
  ('79456c6d-3ecc-5265-a64c-4b06e6c949c4', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 13, 13, 'But he said to them, "You give them something to eat." They said, "We have no more than five loaves and two fish, unless we should go and buy food for all these people."'),
  ('042b381a-50dc-5810-ab01-e37c626e63ac', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 14, 14, 'For they were about five thousand men. He said to his disciples, "Make them sit down in groups of about fifty each."'),
  ('581b8404-c8b5-5100-ac83-f63fbea758f4', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 15, 15, 'They did so, and made them all sit down.'),
  ('e93f09fe-aa8f-5cce-a946-edbfc842a43c', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 16, 16, 'He took the five loaves and the two fish, and looking up to the sky, he blessed them, and broke them, and gave them to the disciples to set before the multitude.'),
  ('b4ec68f5-e34a-56a2-ac85-01e6507ed97b', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 17, 17, 'They ate, and were all filled. They gathered up twelve baskets of broken pieces that were left over.'),
  ('d6f16827-fdb1-54ad-aa18-cd58ce6be0f4', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 18, 18, 'It happened, as he was praying alone, that the disciples were with him, and he asked them, "Who do the multitudes say that I am?"'),
  ('c5230941-7c51-517e-a0a2-b14b20d89519', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 19, 19, 'They answered, "''John the Baptizer,'' but others say, ''Elijah,'' and others, that one of the old prophets is risen again."'),
  ('84b83f80-807f-52c5-a3f6-27c74d45a61e', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 20, 20, 'He said to them, "But who do you say that I am?" Peter answered, "The Christ of God."'),
  ('ab5bbd29-f15a-5b99-af20-182df4ac3b76', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 21, 21, 'But he warned them, and commanded them to tell this to no one,'),
  ('1fa7f61d-68ac-5315-a3ca-6dc4e0221a23', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 22, 22, 'saying, "The Son of Man must suffer many things, and be rejected by the elders, chief priests, and scribes, and be killed, and the third day be raised up."'),
  ('9187114a-9913-5325-aaca-06bb6f78cb14', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 23, 23, 'He said to all, "If anyone desires to come after me, let him deny himself, take up his cross, and follow me.'),
  ('71acbab8-4bce-58c5-afec-5294d1f04262', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 24, 24, 'For whoever desires to save his life will lose it, but whoever will lose his life for my sake, the same will save it.'),
  ('2e4e9328-5e4f-5f7d-a732-c4b911a7ddfd', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 25, 25, 'For what does it profit a man if he gains the whole world, and loses or forfeits his own self?'),
  ('ea4da6cc-1c3f-5122-a086-4e9026ef54d0', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 26, 26, 'For whoever will be ashamed of me and of my words, of him will the Son of Man be ashamed, when he comes in his glory, and the glory of the Father, and of the holy angels.'),
  ('6a8784d1-db45-5a2e-a6ae-5a8dac49d172', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 27, 27, 'But I tell you the truth: There are some of those who stand here, who will in no way taste of death, until they see the Kingdom of God."'),
  ('2e7afc9c-ad39-5e4c-a501-ed687f7da6fc', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 28, 28, 'It happened about eight days after these sayings, that he took with him Peter, John, and James, and went up onto the mountain to pray.'),
  ('a378a400-0324-56f8-a445-0adff1ff8d79', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 29, 29, 'As he was praying, the appearance of his face was altered, and his clothing became white and dazzling.'),
  ('da1598d2-183c-5de2-a174-babb2f1d38bf', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 30, 30, 'Behold, two men were talking with him, who were Moses and Elijah,'),
  ('2b1341d6-9999-59d7-aef4-d288e234faed', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 31, 31, 'who appeared in glory, and spoke of his departure, which he was about to accomplish at Jerusalem.'),
  ('bd63c9b8-4fc6-53d4-a148-32542a8059bc', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 32, 32, 'Now Peter and those who were with him were heavy with sleep, but when they were fully awake, they saw his glory, and the two men who stood with him.'),
  ('e8a6d707-2fac-5abd-acb4-332e4855b24b', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 33, 33, 'It happened, as they were parting from him, that Peter said to Jesus, "Master, it is good for us to be here. Let''s make three tents: one for you, and one for Moses, and one for Elijah," not knowing what he said.'),
  ('7e7212e4-2488-5dce-afa4-296d1d2feae1', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 34, 34, 'While he said these things, a cloud came and overshadowed them, and they were afraid as they entered into the cloud.'),
  ('ac39d0a6-a928-5223-aa0a-3f8044eda9c2', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 35, 35, 'A voice came out of the cloud, saying, "This is my beloved Son. Listen to him!"'),
  ('a3c3017f-e060-5d2f-a32a-fc30fcf0124e', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 36, 36, 'When the voice came, Jesus was found alone. They were silent, and told no one in those days any of the things which they had seen.'),
  ('17e4459a-cf2e-5d74-a21e-095a52160f68', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 37, 37, 'It happened on the next day, when they had come down from the mountain, that a great multitude met him.'),
  ('4c418389-1221-55cc-ad1b-97c2a64dbfe3', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 38, 38, 'Behold, a man from the crowd called out, saying, "Teacher, I beg you to look at my son, for he is my only child.'),
  ('f530dfc5-efd7-5f2b-ab2b-e225d61d3be4', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 39, 39, 'Behold, a spirit takes him, he suddenly cries out, and it convulses him so that he foams, and it hardly departs from him, bruising him severely.'),
  ('5b1a1ba3-19b2-5a2b-ae06-d34e6329291a', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 40, 40, 'I begged your disciples to cast it out, and they couldn''t."'),
  ('02de5adb-3e83-508c-a485-48fa3764b234', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 41, 41, 'Jesus answered, "Faithless and perverse generation, how long shall I be with you and bear with you? Bring your son here."'),
  ('ee9fcd6e-37b6-51cb-ad84-371210e72fd6', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 42, 42, 'While he was still coming, the demon threw him down and convulsed him violently. But Jesus rebuked the unclean spirit, and healed the boy, and gave him back to his father.'),
  ('20e0c4af-ab26-5fbf-a50b-0c809f1c9475', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 43, 43, 'They were all astonished at the majesty of God. But while all were marveling at all the things which Jesus did, he said to his disciples,'),
  ('f704d0fe-fdad-5cfe-a3a6-83e28f0b8457', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 44, 44, '"Let these words sink into your ears, for the Son of Man will be delivered up into the hands of men."'),
  ('194629e2-0da3-5e24-af71-0dbb3a720fc9', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 45, 45, 'But they didn''t understand this saying. It was concealed from them, that they should not perceive it, and they were afraid to ask him about this saying.'),
  ('8831d18d-e734-5024-aa31-b67c7ff13c12', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 46, 46, 'There arose an argument among them about which of them was the greatest.'),
  ('94172120-5a50-581c-af8c-ce06faef4983', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 47, 47, 'Jesus, perceiving the reasoning of their hearts, took a little child, and set him by his side,'),
  ('ae704146-23f1-5bb4-a0c4-cc7c594fb5cd', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 48, 48, 'and said to them, "Whoever receives this little child in my name receives me. Whoever receives me receives him who sent me. For whoever is least among you all, this one will be great."'),
  ('e24fff0a-0bcd-5079-a268-71bc92898dd1', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 49, 49, 'John answered, "Master, we saw someone casting out demons in your name, and we forbade him, because he doesn''t follow with us."'),
  ('4534a832-c0f3-597f-a0a5-d09748da504d', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 50, 50, 'Jesus said to him, "Don''t forbid him, for he who is not against us is for us."'),
  ('2a1f9ea7-ee96-571a-ad2f-9a245ca748e7', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 51, 51, 'It came to pass, when the days were near that he should be taken up, he intently set his face to go to Jerusalem,'),
  ('360a0d88-e468-5e61-a79a-faf9bb581f19', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 52, 52, 'and sent messengers before his face. They went, and entered into a village of the Samaritans, so as to prepare for him.'),
  ('2b451ddf-e9c6-5d0f-a676-45c4617403f4', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 53, 53, 'They didn''t receive him, because he was traveling with his face set towards Jerusalem.'),
  ('622208e5-6ce8-5f12-acd7-3a373ac4adf5', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 54, 54, 'When his disciples, James and John, saw this, they said, "Lord, do you want us to command fire to come down from the sky, and destroy them, just as Elijah did?"'),
  ('5eadc5b2-bd53-5025-ab82-91bda3fd70de', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 55, 55, 'But he turned and rebuked them, "You don''t know of what kind of spirit you are.'),
  ('49d71282-76e5-5de3-aa72-a2a3d65225d8', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 56, 56, 'For the Son of Man didn''t come to destroy men''s lives, but to save them." They went to another village.'),
  ('4bba520b-49db-58fe-a36f-b13a86f25d6f', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 57, 57, 'As they went on the way, a certain man said to him, "I want to follow you wherever you go, Lord."'),
  ('06c88c67-2526-5c11-a8b9-441be2706216', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 58, 58, 'Jesus said to him, "The foxes have holes, and the birds of the sky have nests, but the Son of Man has no place to lay his head."'),
  ('acdfa7e7-5a2a-5dce-a180-2ab0eaf80df9', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 59, 59, 'He said to another, "Follow me!" But he said, "Lord, allow me first to go and bury my father."')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('320b0d07-27e8-5c1a-a3af-df03983a3849', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 60, 60, 'But Jesus said to him, "Leave the dead to bury their own dead, but you go and announce the Kingdom of God."'),
  ('fd128e5a-0107-52d6-a13e-635b7607ce45', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 61, 61, 'Another also said, "I want to follow you, Lord, but first allow me to say good-bye to those who are at my house."'),
  ('5ba3cba6-c5a6-5dce-a984-38f599ab7434', '4b37bdaf-36f9-579e-a6d4-a2d6c48053aa', NULL, 62, 62, 'But Jesus said to him, "No one, having put his hand to the plow, and looking back, is fit for the Kingdom of God."'),
  ('7f4e5a3c-2626-594b-abc5-ab9a373e3168', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 1, 1, 'Now after these things, the Lord also appointed seventy others, and sent them two by two ahead of him into every city and place, where he was about to come.'),
  ('e4c16944-3bec-591d-a8bb-f6597e09b218', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 2, 2, 'Then he said to them, "The harvest is indeed plentiful, but the laborers are few. Pray therefore to the Lord of the harvest, that he may send out laborers into his harvest.'),
  ('5a5aa06c-c72c-5ff2-a365-b1bdc27452bf', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 3, 3, 'Go your ways. Behold, I send you out as lambs among wolves.'),
  ('e0be6608-638c-5183-ad5d-96fbdc593472', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 4, 4, 'Carry no purse, nor wallet, nor sandals. Greet no one on the way.'),
  ('709f0ae1-a7a3-5aed-a345-7fa3fb153229', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 5, 5, 'Into whatever house you enter, first say, ''Peace be to this house.'''),
  ('c991a5b2-8ef3-5a1e-a57c-c81680cc69d0', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 6, 6, 'If a son of peace is there, your peace will rest on him; but if not, it will return to you.'),
  ('ddec2e5d-faf6-5a74-a365-124717366d82', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 7, 7, 'Remain in that same house, eating and drinking the things they give, for the laborer is worthy of his wages. Don''t go from house to house.'),
  ('bd3ca77e-ade5-512c-ac52-8c0778973997', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 8, 8, 'Into whatever city you enter, and they receive you, eat the things that are set before you.'),
  ('6602e090-89f8-5b6e-ab9a-5ebcaaff8b24', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 9, 9, 'Heal the sick who are therein, and tell them, ''The Kingdom of God has come near to you.'''),
  ('f6830e0e-46e7-55f2-af03-0cf04f1e5396', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 10, 10, 'But into whatever city you enter, and they don''t receive you, go out into its streets and say,'),
  ('256a0f3c-051d-593c-a411-1090c22a157b', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 11, 11, '''Even the dust from your city that clings to us, we wipe off against you. Nevertheless know this, that the Kingdom of God has come near to you.'''),
  ('c2ab3c7d-6568-518e-a248-8c6e96a49881', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 12, 12, 'I tell you, it will be more tolerable in that day for Sodom than for that city.'),
  ('3d3447e4-8837-5ff0-a340-e54d15dc542f', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 13, 13, '"Woe to you, Chorazin! Woe to you, Bethsaida! For if the mighty works had been done in Tyre and Sidon which were done in you, they would have repented long ago, sitting in sackcloth and ashes.'),
  ('c1ee5496-ed93-52f3-af6f-49cc86c06f20', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 14, 14, 'But it will be more tolerable for Tyre and Sidon in the judgment than for you.'),
  ('7f20e879-a084-5bbc-a61c-c59479fcd0b7', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 15, 15, 'You, Capernaum, who are exalted to heaven, will be brought down to Hades.'),
  ('80996114-555d-588a-aace-537437e1b86c', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 16, 16, 'Whoever listens to you listens to me, and whoever rejects you rejects me. Whoever rejects me rejects him who sent me."'),
  ('e8a07777-6392-574f-a289-3924f7fbba71', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 17, 17, 'The seventy returned with joy, saying, "Lord, even the demons are subject to us in your name!"'),
  ('23363f8f-af4e-50a7-ad31-6fac473bdf40', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 18, 18, 'He said to them, "I saw Satan having fallen like lightning from heaven.'),
  ('0c0cf0e8-5fbb-5991-afc1-6c6433fc72a9', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 19, 19, 'Behold, I give you authority to tread on serpents and scorpions, and over all the power of the enemy. Nothing will in any way hurt you.'),
  ('7ad4b88c-c9e0-50b2-ad4b-bc8a377e49f8', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 20, 20, 'Nevertheless, don''t rejoice in this, that the spirits are subject to you, but rejoice that your names are written in heaven."'),
  ('353e3bb8-dfa6-5202-ad22-1466102a9700', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 21, 21, 'In that same hour Jesus rejoiced in the Holy Spirit, and said, "I thank you, O Father, Lord of heaven and earth, that you have hidden these things from the wise and understanding, and revealed them to little children. Yes, Father, for so it was well-pleasing in your sight."'),
  ('fb7516a3-ad25-590f-a3a2-5ae7be9ff7d0', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 22, 22, 'Turning to the disciples, he said, "All things have been delivered to me by my Father. No one knows who the Son is, except the Father, and who the Father is, except the Son, and he to whomever the Son desires to reveal him."'),
  ('66cdf045-e680-534c-a4c6-1ed665a7980e', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 23, 23, 'Turning to the disciples, he said privately, "Blessed are the eyes which see the things that you see,'),
  ('c1d00934-6b5d-5f71-ad1b-8dd2a01baf31', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 24, 24, 'for I tell you that many prophets and kings desired to see the things which you see, and didn''t see them, and to hear the things which you hear, and didn''t hear them."'),
  ('213ce8b1-803b-5dbb-a3e6-aa417d81b9d4', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 25, 25, 'Behold, a certain lawyer stood up and tested him, saying, "Teacher, what shall I do to inherit eternal life?"'),
  ('4c8d7f13-c32a-54e9-a5f6-dc1292107343', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 26, 26, 'He said to him, "What is written in the law? How do you read it?"'),
  ('b4a53405-5a0c-5e77-a754-d4f6b2ff7eb4', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 27, 27, 'He answered, "You shall love the Lord your God with all your heart, with all your soul, with all your strength, and with all your mind; and your neighbor as yourself."'),
  ('92bf8882-ba3b-56f8-a831-55c7c41ee0f9', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 28, 28, 'He said to him, "You have answered correctly. Do this, and you will live."'),
  ('284acebc-9c27-5c85-a787-d0768651e75b', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 29, 29, 'But he, desiring to justify himself, asked Jesus, "Who is my neighbor?"'),
  ('4896b113-a72f-5eb1-abdc-05f4bc186040', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 30, 30, 'Jesus answered, "A certain man was going down from Jerusalem to Jericho, and he fell among robbers, who both stripped him and beat him, and departed, leaving him half dead.'),
  ('9f56c0a9-a1be-590b-ac6b-20269d7436ed', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 31, 31, 'By chance a certain priest was going down that way. When he saw him, he passed by on the other side.'),
  ('532c525b-a104-5b09-aed3-a0e8508b256f', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 32, 32, 'In the same way a Levite also, when he came to the place, and saw him, passed by on the other side.'),
  ('4451ec35-47ca-5211-a56b-23c1a3dce11a', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 33, 33, 'But a certain Samaritan, as he traveled, came where he was. When he saw him, he was moved with compassion,'),
  ('d45b3d49-e93e-5f8c-a6c3-698e024696da', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 34, 34, 'came to him, and bound up his wounds, pouring on oil and wine. He set him on his own animal, and brought him to an inn, and took care of him.'),
  ('d25879c1-6ed9-5657-abd3-382bedfda993', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 35, 35, 'On the next day, when he departed, he took out two denarii, and gave them to the host, and said to him, ''Take care of him. Whatever you spend beyond that, I will repay you when I return.'''),
  ('5b479c29-ee9b-51b5-a8e5-5d2b9ff27aa8', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 36, 36, 'Now which of these three do you think seemed to be a neighbor to him who fell among the robbers?"'),
  ('fdfc62ac-2ece-5f0c-a1fb-2ab81f34be76', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 37, 37, 'He said, "He who showed mercy on him." Then Jesus said to him, "Go and do likewise."'),
  ('c65fdf1e-b4c4-5089-aa43-b42006fb4c6c', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 38, 38, 'It happened as they went on their way, he entered into a certain village, and a certain woman named Martha received him into her house.'),
  ('ea597f2d-df39-55b5-aec6-fe47d2db91a3', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 39, 39, 'She had a sister called Mary, who also sat at Jesus'' feet, and heard his word.'),
  ('46fc2b93-f0b0-5ecd-addb-fcf812bb6023', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 40, 40, 'But Martha was distracted with much serving, and she came up to him, and said, "Lord, don''t you care that my sister left me to serve alone? Ask her therefore to help me."'),
  ('5514f1dd-e4a4-5f42-adaf-f6642f9e4f24', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 41, 41, 'Jesus answered her, "Martha, Martha, you are anxious and troubled about many things,'),
  ('4745a6f3-075a-582e-a542-2cfc37d4e4b6', 'b8b2435c-7002-5941-a17b-909a4c1946ba', NULL, 42, 42, 'but one thing is needed. Mary has chosen the good part, which will not be taken away from her."'),
  ('e6b610b4-f826-5ebf-ade1-23d107c90933', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 1, 1, 'It happened, that when he finished praying in a certain place, one of his disciples said to him, "Lord, teach us to pray, just as John also taught his disciples."'),
  ('16af6776-940d-547e-a5c5-41b622d94616', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 2, 2, 'He said to them, "When you pray, say, ''Our Father in heaven, may your name be kept holy. May your Kingdom come. May your will be done on Earth, as it is in heaven.'),
  ('62110893-ef48-5145-a254-d5e2b0117307', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 3, 3, 'Give us day by day our daily bread.'),
  ('5bc34866-0e34-5557-a468-cafcc0332941', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 4, 4, 'Forgive us our sins, for we ourselves also forgive everyone who is indebted to us. Bring us not into temptation, but deliver us from the evil one.''"'),
  ('67787f80-33cb-5140-a476-1bdd11e53dd8', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 5, 5, 'He said to them, "Which of you, if you go to a friend at midnight, and tell him, ''Friend, lend me three loaves of bread,'),
  ('06807f88-b065-5849-af3b-200340018fad', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 6, 6, 'for a friend of mine has come to me from a journey, and I have nothing to set before him,'''),
  ('e89de802-73e0-519d-a35d-9f8962b6fe86', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 7, 7, 'and he from within will answer and say, ''Don''t bother me. The door is now shut, and my children are with me in bed. I can''t get up and give it to you''?'),
  ('6978f66c-0c9f-5c12-a5fe-4c97164ec7fa', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 8, 8, 'I tell you, although he will not rise and give it to him because he is his friend, yet because of his persistence, he will get up and give him as many as he needs.'),
  ('9a4c03f9-ed9a-52d6-a038-fb8858399762', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 9, 9, '"I tell you, keep asking, and it will be given you. Keep seeking, and you will find. Keep knocking, and it will be opened to you.'),
  ('5e5a2ddd-fe60-59e0-aa04-597e9567a03e', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 10, 10, 'For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.'),
  ('f92ac548-6a90-5b5b-a893-ae4880d0a2d1', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 11, 11, '"Which of you fathers, if your son asks for bread, will give him a stone? Or if he asks for a fish, he won''t give him a snake instead of a fish, will he?'),
  ('4a477498-94b3-543f-af42-00788b655e15', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 12, 12, 'Or if he asks for an egg, he won''t give him a scorpion, will he?'),
  ('4fba6e0d-c214-560c-af72-01c55238b220', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 13, 13, 'If you then, being evil, know how to give good gifts to your children, how much more will your heavenly Father give the Holy Spirit to those who ask him?"'),
  ('62f987dc-182c-568e-ae45-30e825a1f4fb', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 14, 14, 'He was casting out a demon, and it was mute. It happened, when the demon had gone out, the mute man spoke; and the multitudes marveled.'),
  ('80768f81-e59d-5815-aba3-0ea118c25364', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 15, 15, 'But some of them said, "He casts out demons by Beelzebul, the prince of the demons."'),
  ('362233a2-4740-56ba-a98d-3a71cd17fb69', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 16, 16, 'Others, testing him, sought from him a sign from heaven.'),
  ('bfc6e01b-709a-5939-a470-28fd724f446d', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 17, 17, 'But he, knowing their thoughts, said to them, "Every kingdom divided against itself is brought to desolation. A house divided against itself falls.'),
  ('05883793-7b84-58fb-a99f-18f3bbec21d3', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 18, 18, 'If Satan also is divided against himself, how will his kingdom stand? For you say that I cast out demons by Beelzebul.'),
  ('3ea7479f-c5a6-50fa-a57d-ccbb5397f478', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 19, 19, 'But if I cast out demons by Beelzebul, by whom do your children cast them out? Therefore will they be your judges.'),
  ('8da3f42b-0d51-5abf-aff1-158e644f1c16', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 20, 20, 'But if I by the finger of God cast out demons, then the Kingdom of God has come to you.'),
  ('5ed5d817-0a04-5769-ad76-e8a17fa3119a', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 21, 21, '"When the strong man, fully armed, guards his own dwelling, his goods are safe.'),
  ('dc94ac5d-375c-52ec-aa14-c58f6cc763c0', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 22, 22, 'But when someone stronger attacks him and overcomes him, he takes from him his whole armor in which he trusted, and divides his spoils.'),
  ('914f56bb-30f3-5d1e-a4c7-f2692580fb66', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 23, 23, '"He that is not with me is against me. He who doesn''t gather with me scatters.'),
  ('c0f0a329-eef8-5137-a12b-80f742ed984a', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 24, 24, 'The unclean spirit, when he has gone out of the man, passes through dry places, seeking rest, and finding none, he says, ''I will turn back to my house from which I came out.'''),
  ('d94cff48-a43a-500a-a91e-68545a200961', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 25, 25, 'When he returns, he finds it swept and put in order.'),
  ('541e3844-4c19-5ebc-a732-a428d467b536', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 26, 26, 'Then he goes, and takes seven other spirits more evil than himself, and they enter in and dwell there. The last state of that man becomes worse than the first."'),
  ('0382f769-f170-51f3-a69e-b0e0af3cb59c', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 27, 27, 'It came to pass, as he said these things, a certain woman out of the multitude lifted up her voice, and said to him, "Blessed is the womb that bore you, and the breasts which nursed you!"'),
  ('b0f78461-6206-5cc1-aea9-f7b7ecd11c81', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 28, 28, 'But he said, "On the contrary, blessed are those who hear the word of God, and keep it."'),
  ('5d134401-40bb-5f2d-a9ef-4fdfff64ca23', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 29, 29, 'When the multitudes were gathering together to him, he began to say, "This is an evil generation. It seeks after a sign. No sign will be given to it but the sign of Jonah, the prophet.'),
  ('222ff0a0-3c7a-5c4c-a2ea-7602250586e7', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 30, 30, 'For even as Jonah became a sign to the Ninevites, so will also the Son of Man be to this generation.'),
  ('09070f03-6898-5d06-a363-62e2e4f4a1c3', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 31, 31, 'The Queen of the South will rise up in the judgment with the men of this generation, and will condemn them: for she came from the ends of the earth to hear the wisdom of Solomon; and behold, one greater than Solomon is here.'),
  ('6f6b1d3c-3b8f-54d3-aa0f-86517ce1dcea', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 32, 32, 'The men of Nineveh will stand up in the judgment with this generation, and will condemn it: for they repented at the preaching of Jonah, and behold, one greater than Jonah is here.'),
  ('75503c34-7dee-5ec2-a5cc-d2f3b7a0d0f8', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 33, 33, '"No one, when he has lit a lamp, puts it in a cellar or under a basket, but on a stand, that those who come in may see the light.'),
  ('fa9aab7d-e3d4-5f17-a157-6c1af6c973ca', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 34, 34, 'The lamp of the body is the eye. Therefore when your eye is good, your whole body is also full of light; but when it is evil, your body also is full of darkness.'),
  ('03bb89fd-1bdb-529e-ac20-0d039a2c7019', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 35, 35, 'Therefore see whether the light that is in you isn''t darkness.'),
  ('3cbdc56a-57d7-5d87-a2f1-d714f894f5fe', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 36, 36, 'If therefore your whole body is full of light, having no part dark, it will be wholly full of light, as when the lamp with its bright shining gives you light."'),
  ('5e4cf83c-0344-5325-a4b9-cce1bf6f69e3', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 37, 37, 'Now as he spoke, a certain Pharisee asked him to dine with him. He went in, and sat at the table.'),
  ('696db2aa-3df1-5925-a306-5d8dcf3264cd', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 38, 38, 'When the Pharisee saw it, he marveled that he had not first washed himself before dinner.'),
  ('a2e91eac-838d-598f-aadf-1c03217797ec', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 39, 39, 'The Lord said to him, "Now you Pharisees cleanse the outside of the cup and of the platter, but your inward part is full of extortion and wickedness.'),
  ('db2c0d42-3d30-55a1-a431-c05abbfc460b', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 40, 40, 'You foolish ones, didn''t he who made the outside make the inside also?'),
  ('f5bee645-1c97-52ec-ae29-cdc488613d71', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 41, 41, 'But give for gifts to the needy those things which are within, and behold, all things will be clean to you.'),
  ('5c4175f8-2043-5f22-a026-7044b8c3dc54', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 42, 42, 'But woe to you Pharisees! For you tithe mint and rue and every herb, but you bypass justice and the love of God. You ought to have done these, and not to have left the other undone.'),
  ('99b7573c-c140-5819-a3a9-3d2ff60ac869', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 43, 43, 'Woe to you Pharisees! For you love the best seats in the synagogues, and the greetings in the marketplaces.'),
  ('8e448e10-2432-5cdb-abc3-8a88784d4a05', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 44, 44, 'Woe to you, scribes and Pharisees, hypocrites! For you are like hidden graves, and the men who walk over them don''t know it."'),
  ('3a6a2c92-1c7f-5037-af26-81c4df34f82d', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 45, 45, 'One of the lawyers answered him, "Teacher, in saying this you insult us also."'),
  ('b8cd0dc1-1463-567b-af67-555aabc4fe4a', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 46, 46, 'He said, "Woe to you lawyers also! For you load men with burdens that are difficult to carry, and you yourselves won''t even lift one finger to help carry those burdens.'),
  ('6d36ced7-3a29-5e43-a40a-11a3d647a6b5', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 47, 47, 'Woe to you! For you build the tombs of the prophets, and your fathers killed them.'),
  ('6a6a4b3c-c88e-543a-a2d0-c63b6d5d7126', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 48, 48, 'So you testify and consent to the works of your fathers. For they killed them, and you build their tombs.'),
  ('b7d664a6-f660-5c87-aa6f-ca491398f1c6', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 49, 49, 'Therefore also the wisdom of God said, ''I will send to them prophets and apostles; and some of them they will kill and persecute,'),
  ('5b77bc34-a917-51c3-af5a-a338c27d8cea', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 50, 50, 'that the blood of all the prophets, which was shed from the foundation of the world, may be required of this generation;'),
  ('0f5ccc8b-9cbe-5937-afe3-f09362758748', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 51, 51, 'from the blood of Abel to the blood of Zachariah, who perished between the altar and the sanctuary.'' Yes, I tell you, it will be required of this generation.'),
  ('9f979857-8bf2-5fd9-a80a-01143cdffc0f', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 52, 52, 'Woe to you lawyers! For you took away the key of knowledge. You didn''t enter in yourselves, and those who were entering in, you hindered."'),
  ('e910687e-1d4d-5cb5-aa38-cad77d56aaa5', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 53, 53, 'As he said these things to them, the scribes and the Pharisees began to be terribly angry, and to draw many things out of him;'),
  ('42f7110c-8464-5034-ad5f-9c26823ddc28', '71760252-e1d2-5c49-a341-e06b6c084f11', NULL, 54, 54, 'lying in wait for him, and seeking to catch him in something he might say, that they might accuse him.'),
  ('e8b78a27-f1d3-56e7-a54c-3dbb58f76fed', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 1, 1, 'Meanwhile, when a multitude of many thousands had gathered together, so much so that they trampled on each other, he began to tell his disciples first of all, "Beware of the yeast of the Pharisees, which is hypocrisy.'),
  ('fe05b258-fa2c-5749-a6db-b4dbc21cd103', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 2, 2, 'But there is nothing covered up, that will not be revealed, nor hidden, that will not be known.'),
  ('285515ad-c5c2-5479-aca5-7e354bb7818b', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 3, 3, 'Therefore whatever you have said in the darkness will be heard in the light. What you have spoken in the ear in the inner rooms will be proclaimed on the housetops.'),
  ('b538608d-5728-560d-acc0-327bc998437b', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 4, 4, '"I tell you, my friends, don''t be afraid of those who kill the body, and after that have no more that they can do.'),
  ('e4e8f16c-ee5b-5704-a044-9d563b7566c5', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 5, 5, 'But I will warn you whom you should fear. Fear him, who after he has killed, has power to cast into Gehenna. Yes, I tell you, fear him.'),
  ('6cd14513-b896-5c96-a9cf-0b3711fdd45f', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 6, 6, '"Aren''t five sparrows sold for two assaria coins? Not one of them is forgotten by God.'),
  ('26ea5a93-533b-54bc-a465-211cf9dff100', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 7, 7, 'But the very hairs of your head are all numbered. Therefore don''t be afraid. You are of more value than many sparrows.'),
  ('75dd9dff-ad01-59cd-ad83-1caaee4f1c80', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 8, 8, '"I tell you, everyone who confesses me before men, him will the Son of Man also confess before the angels of God;'),
  ('5db731ea-3315-5fc4-a0cb-d040b87ef9b5', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 9, 9, 'but he who denies me in the presence of men will be denied in the presence of the angels of God.'),
  ('1a532bb3-145c-5265-ad70-3e568e1688fe', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 10, 10, 'Everyone who speaks a word against the Son of Man will be forgiven, but those who blaspheme against the Holy Spirit will not be forgiven.'),
  ('7f79d4a3-02cc-5a92-a2a3-d982ddbe8496', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 11, 11, 'When they bring you before the synagogues, the rulers, and the authorities, don''t be anxious how or what you will answer, or what you will say;'),
  ('e526b4ff-3e30-5de4-aa07-436366a63c28', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 12, 12, 'for the Holy Spirit will teach you in that same hour what you must say."'),
  ('55c3214a-12a9-5ece-a1dc-bb6d0724bd83', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 13, 13, 'One of the multitude said to him, "Teacher, tell my brother to divide the inheritance with me."'),
  ('e0dbb70e-880f-59b1-a265-b8d93cac4b87', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 14, 14, 'But he said to him, "Man, who made me a judge or an arbitrator over you?"'),
  ('32d3c2fd-1a25-508f-afca-b6631acea61c', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 15, 15, 'He said to them, "Beware! Keep yourselves from covetousness, for a man''s life doesn''t consist of the abundance of the things which he possesses."'),
  ('4367f988-e603-5a3e-a9eb-3e1b58d1e768', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 16, 16, 'He spoke a parable to them, saying, "The ground of a certain rich man brought forth abundantly.'),
  ('c1db674a-cda7-58db-abdf-d2abaf4c31f2', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 17, 17, 'He reasoned within himself, saying, ''What will I do, because I don''t have room to store my crops?'''),
  ('9565bd29-0ea7-5b0e-a887-6d290ad27a53', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 18, 18, 'He said, ''This is what I will do. I will pull down my barns, and build bigger ones, and there I will store all my grain and my goods.'),
  ('2a81d248-bd95-57dd-a9cd-1fb8c195ae3e', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 19, 19, 'I will tell my soul, "Soul, you have many goods laid up for many years. Take your ease, eat, drink, be merry."'''),
  ('4ccad10e-cc7c-5ada-ab35-6e17143e6d11', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 20, 20, '"But God said to him, ''You foolish one, tonight your soul is required of you. The things which you have prepared--whose will they be?'''),
  ('8b99297e-c106-5575-a658-9cfa945f91a0', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 21, 21, 'So is he who lays up treasure for himself, and is not rich toward God."'),
  ('ca5fbd55-ed07-534f-a05c-8efdc2fd05e6', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 22, 22, 'He said to his disciples, "Therefore I tell you, don''t be anxious for your life, what you will eat, nor yet for your body, what you will wear.'),
  ('fb402cb9-e059-52aa-a629-1239f89d804c', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 23, 23, 'Life is more than food, and the body is more than clothing.'),
  ('7ac5987d-4bd1-5688-a638-82d025284567', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 24, 24, 'Consider the ravens: they don''t sow, they don''t reap, they have no warehouse or barn, and God feeds them. How much more valuable are you than birds!'),
  ('5e646154-418d-5daa-a46c-d9d01371fccd', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 25, 25, 'Which of you by being anxious can add a cubit to his height?'),
  ('32892f66-ed1e-5fb6-a30b-ec5d79b88100', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 26, 26, 'If then you aren''t able to do even the least things, why are you anxious about the rest?'),
  ('2616ae8f-11ce-558d-a9a5-e53e96ea0459', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 27, 27, 'Consider the lilies, how they grow. They don''t toil, neither do they spin; yet I tell you, even Solomon in all his glory was not arrayed like one of these.'),
  ('212e8049-b367-5ffd-a316-3bfcf2477a67', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 28, 28, 'But if this is how God clothes the grass in the field, which today exists, and tomorrow is cast into the oven, how much more will he clothe you, O you of little faith?'),
  ('dd898a6e-3805-5254-aef6-7a5f5e4887d5', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 29, 29, 'Don''t seek what you will eat or what you will drink; neither be anxious.'),
  ('d6429a3f-87c5-5434-ac6e-938da4e09fdc', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 30, 30, 'For the nations of the world seek after all of these things, but your Father knows that you need these things.'),
  ('ce14db33-fa63-5889-affb-cba5fb0ee943', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 31, 31, 'But seek God''s Kingdom, and all these things will be added to you.'),
  ('e5399d53-5fba-5c47-aff2-7bc836a4b8de', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 32, 32, 'Don''t be afraid, little flock, for it is your Father''s good pleasure to give you the Kingdom.'),
  ('a4047e18-347e-514e-aa61-b956c3caa569', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 33, 33, 'Sell that which you have, and give gifts to the needy. Make for yourselves purses which don''t grow old, a treasure in the heavens that doesn''t fail, where no thief approaches, neither moth destroys.'),
  ('fcd78eb5-cd02-576c-ad9b-87e9bec37e2c', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 34, 34, 'For where your treasure is, there will your heart be also.'),
  ('4c77310e-2840-5b55-ab55-52818c8141e1', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 35, 35, '"Let your waist be dressed and your lamps burning.'),
  ('e1d33b56-6424-5360-aea9-d10ca3959786', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 36, 36, 'Be like men watching for their lord, when he returns from the marriage feast; that, when he comes and knocks, they may immediately open to him.'),
  ('ef1c626a-9993-59cf-ad5d-4009a0297aae', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 37, 37, 'Blessed are those servants, whom the lord will find watching when he comes. Most certainly I tell you, that he will dress himself, and make them recline, and will come and serve them.'),
  ('83f4a31c-acc9-5672-ab94-40d7849e699b', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 38, 38, 'They will be blessed if he comes in the second or third watch, and finds them so.'),
  ('44602458-3300-5557-acba-03c819e002b0', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 39, 39, 'But know this, that if the master of the house had known in what hour the thief was coming, he would have watched, and not allowed his house to be broken into.'),
  ('f73682ac-d12c-5f83-a072-c9f9feaa3581', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 40, 40, 'Therefore be ready also, for the Son of Man is coming in an hour that you don''t expect him."'),
  ('67735f50-16cc-5b68-acea-afc0296530b0', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 41, 41, 'Peter said to him, "Lord, are you telling this parable to us, or to everybody?"'),
  ('5c28f053-87d8-52d4-a305-dce603b67f23', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 42, 42, 'The Lord said, "Who then is the faithful and wise steward, whom his lord will set over his household, to give them their portion of food at the right times?'),
  ('125615ed-6fdf-58ce-a8d6-dcf3e4c0a416', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 43, 43, 'Blessed is that servant whom his lord will find doing so when he comes.'),
  ('3c5f38bc-bd9d-5732-a61b-74bdf73ddec5', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 44, 44, 'Truly I tell you, that he will set him over all that he has.'),
  ('e5c8348c-304c-57e6-a9a7-bdc9bdca7bff', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 45, 45, 'But if that servant says in his heart, ''My lord delays his coming,'' and begins to beat the menservants and the maidservants, and to eat and drink, and to be drunken,'),
  ('01f95688-8cc6-55ce-a7cf-e54eaa4f1596', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 46, 46, 'then the lord of that servant will come in a day when he isn''t expecting him, and in an hour that he doesn''t know, and will cut him in two, and place his portion with the unfaithful.'),
  ('96dcb262-708d-584e-abd3-70fa977ee2d4', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 47, 47, 'That servant, who knew his lord''s will, and didn''t prepare, nor do what he wanted, will be beaten with many stripes,'),
  ('8f33f585-99a0-5ebb-aead-3897b85ec747', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 48, 48, 'but he who didn''t know, and did things worthy of stripes, will be beaten with few stripes. To whoever much is given, of him will much be required; and to whom much was entrusted, of him more will be asked.'),
  ('971efa10-db41-57f0-a93c-ee3e2957b8a4', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 49, 49, '"I came to throw fire on the earth. I wish it were already kindled.'),
  ('e3d01970-936d-5f3d-a036-6deec6e8103f', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 50, 50, 'But I have a baptism to be baptized with, and how distressed I am until it is accomplished!'),
  ('03fb4b68-a497-5009-aeb6-1f50d0d7a57d', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 51, 51, 'Do you think that I have come to give peace in the earth? I tell you, no, but rather division.'),
  ('e2917112-60f6-5dba-a2ed-d54e0618ccc6', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 52, 52, 'For from now on, there will be five in one house divided, three against two, and two against three.'),
  ('e227fddf-d419-562a-adcf-13a934896cad', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 53, 53, 'They will be divided, father against son, and son against father; mother against daughter, and daughter against her mother; mother-in-law against her daughter-in-law, and daughter-in-law against her mother-in-law."'),
  ('7a246b58-2dd6-5468-a505-51cabae11b09', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 54, 54, 'He said to the multitudes also, "When you see a cloud rising from the west, immediately you say, ''A shower is coming,'' and so it happens.'),
  ('b24f17b1-9182-5ffb-a296-2a671a4fd99f', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 55, 55, 'When a south wind blows, you say, ''There will be a scorching heat,'' and it happens.'),
  ('eafaca4b-d60a-5d3f-a60c-281131a6edc4', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 56, 56, 'You hypocrites! You know how to interpret the appearance of the earth and the sky, but how is it that you don''t interpret this time?'),
  ('8f6f49c4-e7f5-5d9c-ada6-94d929455eeb', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 57, 57, 'Why don''t you judge for yourselves what is right?'),
  ('e24b0f94-a19b-5841-aa95-4d197d0e6294', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 58, 58, 'For when you are going with your adversary before the magistrate, try diligently on the way to be released from him, lest perhaps he drag you to the judge, and the judge deliver you to the officer, and the officer throw you into prison.'),
  ('1d2127cf-8bc5-5ce7-a248-f7e9a3a0ffc7', 'ceeda637-58a0-5bc8-a751-3d63389ed645', NULL, 59, 59, 'I tell you, you will by no means get out of there, until you have paid the very last penny."'),
  ('4703535d-f1bb-54c7-a7a8-0674d4fb5ec1', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 1, 1, 'Now there were some present at the same time who told him about the Galileans, whose blood Pilate had mixed with their sacrifices.'),
  ('000a596c-bfd4-5d6b-aa53-a26dcb69d0ce', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 2, 2, 'Jesus answered them, "Do you think that these Galileans were worse sinners than all the other Galileans, because they suffered such things?'),
  ('3266039b-59ae-50a7-af87-4f7f8fe09005', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 3, 3, 'I tell you, no, but unless you repent, you will all perish in the same way.'),
  ('560f92c1-d938-5b54-af21-9a3af7f3b301', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 4, 4, 'Or those eighteen, on whom the tower in Siloam fell, and killed them; do you think that they were worse offenders than all the men who dwell in Jerusalem?'),
  ('879ba2a7-4175-5eb2-a41e-6f7a14810f6b', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 5, 5, 'I tell you, no, but, unless you repent, you will all perish in the same way."'),
  ('476b78b3-7f8a-5f97-ab67-2c0bcf3b6826', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 6, 6, 'He spoke this parable. "A certain man had a fig tree planted in his vineyard, and he came seeking fruit on it, and found none.'),
  ('df750f14-3c92-58b5-a330-961457a5cb42', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 7, 7, 'He said to the vine dresser, ''Behold, these three years I have come looking for fruit on this fig tree, and found none. Cut it down. Why does it waste the soil?'''),
  ('76a0e28e-afb4-5aa2-a2ed-835d9c65cbe1', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 8, 8, 'He answered, ''Lord, leave it alone this year also, until I dig around it, and fertilize it.'),
  ('0ae61e60-e79c-59fd-a968-22301dfdc796', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 9, 9, 'If it bears fruit, fine; but if not, after that, you can cut it down.''"'),
  ('8fd09e91-fc28-54a1-a8d7-b9d1b0f4fcd8', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 10, 10, 'He was teaching in one of the synagogues on the Sabbath day.'),
  ('5af56bb8-0c2c-521e-a242-be43603d8a3b', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 11, 11, 'Behold, there was a woman who had a spirit of infirmity eighteen years, and she was bent over, and could in no way straighten herself up.'),
  ('09783260-2aee-574d-a67d-1cb2be481ca7', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 12, 12, 'When Jesus saw her, he called her, and said to her, "Woman, you are freed from your infirmity."'),
  ('3c9384d4-da35-5b47-a2ff-a2968389e50a', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 13, 13, 'He laid his hands on her, and immediately she stood up straight, and glorified God.'),
  ('80c6ece4-547e-51c7-a40c-3fac1e8a7053', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 14, 14, 'The ruler of the synagogue, being indignant because Jesus had healed on the Sabbath, said to the multitude, "There are six days in which men ought to work. Therefore come on those days and be healed, and not on the Sabbath day!"'),
  ('79bb1a30-1103-576f-af16-b83a9a4b2b4e', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 15, 15, 'Therefore the Lord answered him, "You hypocrites! Doesn''t each one of you free his ox or his donkey from the stall on the Sabbath, and lead him away to water?'),
  ('74637067-004b-5fc2-acf1-1726aee68ec9', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 16, 16, 'Ought not this woman, being a daughter of Abraham, whom Satan had bound eighteen long years, be freed from this bondage on the Sabbath day?"'),
  ('cb39a11a-f74f-5ca3-a2d7-d8458040536f', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 17, 17, 'As he said these things, all his adversaries were disappointed, and all the multitude rejoiced for all the glorious things that were done by him.'),
  ('63cbeac4-6358-529a-a751-1c92d0f6f536', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 18, 18, 'He said, "What is the Kingdom of God like? To what shall I compare it?'),
  ('4f007731-262d-559e-ae1d-b0e11a3bafc9', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 19, 19, 'It is like a grain of mustard seed, which a man took, and put in his own garden. It grew, and became a large tree, and the birds of the sky lodged in its branches."'),
  ('1f2e1508-0835-5693-a524-64fe03183630', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 20, 20, 'Again he said, "To what shall I compare the Kingdom of God?'),
  ('bc13640e-55c1-5914-a74f-77b0413af178', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 21, 21, 'It is like yeast, which a woman took and hid in three measures of flour, until it was all leavened."'),
  ('581bb9d8-7bd6-58f2-a417-8f2b87dc22d0', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 22, 22, 'He went on his way through cities and villages, teaching, and traveling on to Jerusalem.'),
  ('f3475533-cdcc-5761-af78-2644df7ce41b', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 23, 23, 'One said to him, "Lord, are they few who are saved?" He said to them,'),
  ('9369f870-6387-5ace-aed9-a5997dbd9a06', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 24, 24, '"Strive to enter in by the narrow door, for many, I tell you, will seek to enter in, and will not be able.'),
  ('c33fae38-f96e-5f7e-a2d3-bf164475b6d0', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 25, 25, 'When once the master of the house has risen up, and has shut the door, and you begin to stand outside, and to knock at the door, saying, ''Lord, Lord, open to us!'' then he will answer and tell you, ''I don''t know you or where you come from.'''),
  ('9277e66d-33cb-5eea-a753-11cb1add9189', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 26, 26, 'Then you will begin to say, ''We ate and drank in your presence, and you taught in our streets.'''),
  ('169163ed-a17b-539d-a61a-d5ebdef99e34', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 27, 27, 'He will say, ''I tell you, I don''t know where you come from. Depart from me, all you workers of iniquity.'''),
  ('30b7f94c-9e9e-57f3-ae73-5aa0a4ed5781', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 28, 28, 'There will be weeping and gnashing of teeth, when you see Abraham, Isaac, Jacob, and all the prophets, in the Kingdom of God, and yourselves being thrown outside.'),
  ('5507f7d0-94c8-58b1-a0a5-4de360451771', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 29, 29, 'They will come from the east, west, north, and south, and will sit down in the Kingdom of God.'),
  ('2364c2fe-b3d5-5791-a23e-d74ebfe0399a', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 30, 30, 'Behold, there are some who are last who will be first, and there are some who are first who will be last."'),
  ('4c003375-75bd-580d-a2ce-ceddf86b6d37', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 31, 31, 'On that same day, some Pharisees came, saying to him, "Get out of here, and go away, for Herod wants to kill you."'),
  ('08c190e5-e485-5c42-ad72-88826ee69d85', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 32, 32, 'He said to them, "Go and tell that fox, ''Behold, I cast out demons and perform cures today and tomorrow, and the third day I complete my mission.'),
  ('12501861-d8e1-5415-a337-d5647ee50fa1', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 33, 33, 'Nevertheless I must go on my way today and tomorrow and the next day, for it can''t be that a prophet perish outside of Jerusalem.'''),
  ('09ed0387-17b9-51b4-a8fa-7839101ef732', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 34, 34, '"Jerusalem, Jerusalem, that kills the prophets, and stones those who are sent to her! How often I wanted to gather your children together, like a hen gathers her own brood under her wings, and you refused!'),
  ('f8c2a331-4bce-5e5e-ad7f-1b287d564614', '59f3f928-f3d6-5348-aa32-e3cc0574517b', NULL, 35, 35, 'Behold, your house is left to you desolate. I tell you, you will not see me, until you say, ''Blessed is he who comes in the name of the Lord!''"'),
  ('30e9a5c0-762d-56c4-a69e-02205aabebf7', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 1, 1, 'It happened, when he went into the house of one of the rulers of the Pharisees on a Sabbath to eat bread, that they were watching him.'),
  ('c374fe72-571e-5d5f-aa65-2454f5251a1d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 2, 2, 'Behold, a certain man who had dropsy was in front of him.'),
  ('974ddc29-1708-5451-a889-03ffbbaed84d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 3, 3, 'Jesus, answering, spoke to the lawyers and Pharisees, saying, "Is it lawful to heal on the Sabbath?"'),
  ('fb3ecbc8-fbb8-512c-ab3d-ae7f6fe77e53', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 4, 4, 'But they were silent. He took him, and healed him, and let him go.'),
  ('ae43c291-294d-5a69-a1d8-c302e9b90a0d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 5, 5, 'He answered them, "Which of you, if your son or an ox fell into a well, wouldn''t immediately pull him out on a Sabbath day?"'),
  ('7ca6fead-6d67-5885-aeab-1e37a1ad1bd3', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 6, 6, 'They couldn''t answer him regarding these things.'),
  ('c09baafd-830b-5b96-a8a5-2f3d13849ef8', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 7, 7, 'He spoke a parable to those who were invited, when he noticed how they chose the best seats, and said to them,'),
  ('f2d3728b-729b-58e0-a48e-be96145073a2', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 8, 8, '"When you are invited by anyone to a marriage feast, don''t sit in the best seat, since perhaps someone more honorable than you might be invited by him,'),
  ('b9b1d4e1-5aff-5313-a266-cf0595a4887a', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 9, 9, 'and he who invited both of you would come and tell you, ''Make room for this person.'' Then you would begin, with shame, to take the lowest place.'),
  ('ed540f6b-7055-51f5-a0df-e99b8419e5f6', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 10, 10, 'But when you are invited, go and sit in the lowest place, so that when he who invited you comes, he may tell you, ''Friend, move up higher.'' Then you will be honored in the presence of all who sit at the table with you.'),
  ('9a1b5045-8c86-59c4-aecc-7df0af739296', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 11, 11, 'For everyone who exalts himself will be humbled, and whoever humbles himself will be exalted."'),
  ('2c131da8-b747-5e73-a45d-dce45913bb0f', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 12, 12, 'He also said to the one who had invited him, "When you make a dinner or a supper, don''t call your friends, nor your brothers, nor your kinsmen, nor rich neighbors, or perhaps they might also return the favor, and pay you back.'),
  ('746583d9-5ec1-5f6d-ab33-9cf42af45c03', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 13, 13, 'But when you make a feast, ask the poor, the maimed, the lame, or the blind;'),
  ('90cc5563-a274-5f27-aee9-a77c3c420cd2', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 14, 14, 'and you will be blessed, because they don''t have the resources to repay you. For you will be repaid in the resurrection of the righteous."'),
  ('165b41af-b7e6-51f0-a8fc-b15a075a2abe', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 15, 15, 'When one of those who sat at the table with him heard these things, he said to him, "Blessed is he who will feast in the Kingdom of God!"'),
  ('94f532bc-2ec9-5666-ae6a-7ebf930a900d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 16, 16, 'But he said to him, "A certain man made a great supper, and he invited many people.'),
  ('12a1a4d8-b73f-50f6-ac6a-e08777de6b0d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 17, 17, 'He sent out his servant at supper time to tell those who were invited, ''Come, for everything is ready now.'''),
  ('7712a606-81ed-5487-a060-7ac28900b25d', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 18, 18, 'They all as one began to make excuses. "The first said to him, ''I have bought a field, and I must go and see it. Please have me excused.'''),
  ('9065dc7b-ea44-5e76-aac3-8bf7a4ba9f1e', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 19, 19, '"Another said, ''I have bought five yoke of oxen, and I must go try them out. Please have me excused.'''),
  ('53980b93-1991-5d45-a4c7-a24aafb99b8a', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 20, 20, '"Another said, ''I have married a wife, and therefore I can''t come.'''),
  ('af8ed891-086b-562b-ac34-a49e68dc2dfd', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 21, 21, '"That servant came, and told his lord these things. Then the master of the house, being angry, said to his servant, ''Go out quickly into the streets and lanes of the city, and bring in the poor, maimed, blind, and lame.'''),
  ('0b8fa7eb-148f-5e78-aead-55a50a030146', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 22, 22, '"The servant said, ''Lord, it is done as you commanded, and there is still room.'''),
  ('b17505cc-47c6-5e45-a492-2033557e160f', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 23, 23, '"The lord said to the servant, ''Go out into the highways and hedges, and compel them to come in, that my house may be filled.'),
  ('2246e2fd-06ef-54ce-ac11-f09c0785ac49', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 24, 24, 'For I tell you that none of those men who were invited will taste of my supper.''"'),
  ('ca39a1bd-f85f-53a9-ad2f-cdedb4343381', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 25, 25, 'Now great multitudes were going with him. He turned and said to them,'),
  ('796d410c-23fe-5184-afa8-8ebe47874362', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 26, 26, '"If anyone comes to me, and doesn''t disregard his own father, mother, wife, children, brothers, and sisters, yes, and his own life also, he can''t be my disciple.'),
  ('401db9d3-8ff7-5cdb-ae35-c916a13f1d38', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 27, 27, 'Whoever doesn''t bear his own cross, and come after me, can''t be my disciple.'),
  ('3d579ef8-872a-579a-ab1c-1c6f807e0d97', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 28, 28, 'For which of you, desiring to build a tower, doesn''t first sit down and count the cost, to see if he has enough to complete it?'),
  ('3f55e702-a512-5cde-a1f9-c99a7cf7dc24', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 29, 29, 'Or perhaps, when he has laid a foundation, and is not able to finish, everyone who sees begins to mock him,'),
  ('a5f33895-e3d3-514d-a8dd-4400eb5f7f47', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 30, 30, 'saying, ''This man began to build, and wasn''t able to finish.'''),
  ('5ffb7c90-fb38-58c5-aa39-edf64001b642', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 31, 31, 'Or what king, as he goes to encounter another king in war, will not sit down first and consider whether he is able with ten thousand to meet him who comes against him with twenty thousand?'),
  ('1707cfc0-78b7-5841-aafb-b1d022de2efa', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 32, 32, 'Or else, while the other is yet a great way off, he sends an envoy, and asks for conditions of peace.'),
  ('5cd89853-1bcb-547e-aabb-be6b8cd69ac5', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 33, 33, 'So therefore whoever of you who doesn''t renounce all that he has, he can''t be my disciple.'),
  ('d55f25ba-cc39-5843-a3b1-7bc1cb67d201', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 34, 34, 'Salt is good, but if the salt becomes flat and tasteless, with what do you season it?'),
  ('fc79b519-5d1c-5dc3-a80e-4d6926fcc8ed', '80c18bf4-4a83-5c28-a638-96d9c30ab87c', NULL, 35, 35, 'It is fit neither for the soil nor for the manure pile. It is thrown out. He who has ears to hear, let him hear."'),
  ('6b9c17d3-26a0-5eb4-a018-d4e160e98f06', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 1, 1, 'Now all the tax collectors and sinners were coming close to him to hear him.'),
  ('0ac4842f-3dfb-56fd-a5a2-5040a9c3465a', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 2, 2, 'The Pharisees and the scribes murmured, saying, "This man welcomes sinners, and eats with them."'),
  ('96ee15a9-4a51-5343-ab2f-f433c91cb2e3', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 3, 3, 'He told them this parable.'),
  ('a20fb528-e1d1-53fd-af4c-a11106e9271b', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 4, 4, '"Which of you men, if you had one hundred sheep, and lost one of them, wouldn''t leave the ninety-nine in the wilderness, and go after the one that was lost, until he found it?'),
  ('cac6d6b0-4ed3-5650-a26f-aa158b44555c', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 5, 5, 'When he has found it, he carries it on his shoulders, rejoicing.'),
  ('448a6826-373a-56ab-af0e-31c6d4bc7cb0', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 6, 6, 'When he comes home, he calls together his friends and his neighbors, saying to them, ''Rejoice with me, for I have found my sheep which was lost!'''),
  ('76e8f31c-498a-5336-ae80-2aa5a2d8e6ba', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 7, 7, 'I tell you that even so there will be more joy in heaven over one sinner who repents, than over ninety-nine righteous people who need no repentance.'),
  ('9882f087-cf87-5b87-aaa4-c9670b79f4de', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 8, 8, 'Or what woman, if she had ten drachma coins, if she lost one drachma coin, wouldn''t light a lamp, sweep the house, and seek diligently until she found it?'),
  ('4f2977da-7afb-5ee9-a672-edaf5683ce93', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 9, 9, 'When she has found it, she calls together her friends and neighbors, saying, ''Rejoice with me, for I have found the drachma which I had lost.'''),
  ('a590f742-b24c-55a7-a6b1-bfc10425a4dd', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 10, 10, 'Even so, I tell you, there is joy in the presence of the angels of God over one sinner repenting."'),
  ('b8a6727d-97a8-53c6-aab7-922022ed862e', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 11, 11, 'He said, "A certain man had two sons.'),
  ('fa24787f-3080-5a71-aa08-a0c8fa672691', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 12, 12, 'The younger of them said to his father, ''Father, give me my share of your property.'' He divided his livelihood between them.'),
  ('56057468-a671-5d69-a450-005748460ac1', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 13, 13, 'Not many days after, the younger son gathered all of this together and traveled into a far country. There he wasted his property with riotous living.'),
  ('e7b6156d-54b2-5f09-a92f-bf6f123768a3', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 14, 14, 'When he had spent all of it, there arose a severe famine in that country, and he began to be in need.'),
  ('58027444-c0c6-5b57-aede-f412fa3c4c61', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 15, 15, 'He went and joined himself to one of the citizens of that country, and he sent him into his fields to feed pigs.'),
  ('3b7537aa-0063-5c82-a003-1c6c17a149a6', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 16, 16, 'He wanted to fill his belly with the husks that the pigs ate, but no one gave him any.'),
  ('fdeba9ca-5204-5d13-ac66-bc5530d3752d', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 17, 17, 'But when he came to himself he said, ''How many hired servants of my father''s have bread enough to spare, and I''m dying with hunger!'),
  ('e07fbfa0-2d1d-594d-afdb-53080e8664fa', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 18, 18, 'I will get up and go to my father, and will tell him, "Father, I have sinned against heaven, and in your sight.'),
  ('6f47341e-ace2-5aef-a2fc-93dbb6621c55', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 19, 19, 'I am no more worthy to be called your son. Make me as one of your hired servants."'''),
  ('c0ab6a63-da3f-5077-a095-695a8ed74370', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 20, 20, '"He arose, and came to his father. But while he was still far off, his father saw him, and was moved with compassion, and ran, and fell on his neck, and kissed him.'),
  ('451670c8-78dc-54ea-a042-54632099b790', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 21, 21, 'The son said to him, ''Father, I have sinned against heaven, and in your sight. I am no longer worthy to be called your son.'''),
  ('bc69eae8-c9c1-5e6e-a909-e85af565d457', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 22, 22, '"But the father said to his servants, ''Bring out the best robe, and put it on him. Put a ring on his hand, and shoes on his feet.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('994c6a49-cdb6-5860-a6da-19d5d8e9b9d2', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 23, 23, 'Bring the fattened calf, kill it, and let us eat, and celebrate;'),
  ('93e16468-1bef-5b82-acb0-47d33047c6f3', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 24, 24, 'for this, my son, was dead, and is alive again. He was lost, and is found.'' They began to celebrate.'),
  ('6460dd9f-e26f-53c3-a757-5bb0cc6fa250', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 25, 25, '"Now his elder son was in the field. As he came near to the house, he heard music and dancing.'),
  ('caaf95f6-6c2e-5c34-a463-ea18243e5775', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 26, 26, 'He called one of the servants to him, and asked what was going on.'),
  ('dd0234c5-5e84-5019-a81c-f35306fde4d6', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 27, 27, 'He said to him, ''Your brother has come, and your father has killed the fattened calf, because he has received him back safe and healthy.'''),
  ('6f39ada7-af84-5196-a614-6d4420b2b211', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 28, 28, 'But he was angry, and would not go in. Therefore his father came out, and begged him.'),
  ('0e7e2dd0-e689-5f09-a207-211d1c0b4b9e', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 29, 29, 'But he answered his father, ''Behold, these many years I have served you, and I never disobeyed a commandment of yours, but you never gave me a goat, that I might celebrate with my friends.'),
  ('e9f3ca3d-dd0d-5ff5-adbb-0c0214f40bf3', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 30, 30, 'But when this, your son, came, who has devoured your living with prostitutes, you killed the fattened calf for him.'''),
  ('6c513e8e-1de2-5433-a156-23284260f4a2', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 31, 31, '"He said to him, ''Son, you are always with me, and all that is mine is yours.'),
  ('b00f6d1b-2e1b-5f9e-a6ea-01a5b3f43cf5', 'bc505c67-d9e1-5edb-afa3-091d7db7b576', NULL, 32, 32, 'But it was appropriate to celebrate and be glad, for this, your brother, was dead, and is alive again. He was lost, and is found.''"'),
  ('78c90026-b138-5482-a035-4a876ed8e979', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 1, 1, 'He also said to his disciples, "There was a certain rich man who had a manager. An accusation was made to him that this man was wasting his possessions.'),
  ('18eb5c50-981a-5d08-abff-50f7e3046543', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 2, 2, 'He called him, and said to him, ''What is this that I hear about you? Give an accounting of your management, for you can no longer be manager.'''),
  ('645ab730-e4bc-5d91-a485-a96bd9ff4d1f', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 3, 3, '"The manager said within himself, ''What will I do, seeing that my lord is taking away the management position from me? I don''t have strength to dig. I am ashamed to beg.'),
  ('2500aefc-e4ee-5bfe-aee8-86ce9242815a', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 4, 4, 'I know what I will do, so that when I am removed from management, they may receive me into their houses.'''),
  ('977b53a6-c3e1-549a-af46-5bf5c2c89f90', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 5, 5, 'Calling each one of his lord''s debtors to him, he said to the first, ''How much do you owe to my lord?'''),
  ('1d4413aa-4437-506c-a989-0551b86a27fd', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 6, 6, 'He said, ''A hundred batos of oil.'' He said to him, ''Take your bill, and sit down quickly and write fifty.'''),
  ('100021aa-b2b0-5243-a93f-16b60836c143', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 7, 7, 'Then he said to another, ''How much do you owe?'' He said, ''A hundred cors of wheat.'' He said to him, ''Take your bill, and write eighty.'''),
  ('f50db35c-8907-5414-a4e4-347cb8ccb08e', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 8, 8, '"His lord commended the dishonest manager because he had done wisely, for the children of this world are, in their own generation, wiser than the children of the light.'),
  ('b782cf8a-37cd-58c9-adf8-c6b0be022554', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 9, 9, 'I tell you, make for yourselves friends by means of unrighteous mammon, so that when you fail, they may receive you into the eternal tents.'),
  ('f00c38d3-ebb3-55f0-a65c-fb943e3178a5', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 10, 10, 'He who is faithful in a very little is faithful also in much. He who is dishonest in a very little is also dishonest in much.'),
  ('8c22b13a-6160-53f1-a7ea-2b449101c661', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 11, 11, 'If therefore you have not been faithful in the unrighteous mammon, who will commit to your trust the true riches?'),
  ('6e30a827-ea2a-5ecb-a633-b514f9e01e5f', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 12, 12, 'If you have not been faithful in that which is another''s, who will give you that which is your own?'),
  ('61331581-e410-5dfd-a77a-b1e666c3dd47', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 13, 13, 'No servant can serve two masters, for either he will hate the one, and love the other; or else he will hold to one, and despise the other. You aren''t able to serve God and mammon."'),
  ('4407154e-a086-5e76-abc5-1332173e6d29', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 14, 14, 'The Pharisees, who were lovers of money, also heard all these things, and they scoffed at him.'),
  ('7dc79e34-671b-53ff-a03c-8b18e0c6bcab', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 15, 15, 'He said to them, "You are those who justify yourselves in the sight of men, but God knows your hearts. For that which is exalted among men is an abomination in the sight of God.'),
  ('bbbc1e7d-c42a-53fc-a718-e6232ecee759', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 16, 16, 'The law and the prophets were until John. From that time the Good News of the Kingdom of God is preached, and everyone is forcing his way into it.'),
  ('2e6d49be-54db-5732-a168-3e0bf55d28c8', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 17, 17, 'But it is easier for heaven and earth to pass away, than for one tiny stroke of a pen in the law to fall.'),
  ('01944b63-98a5-553c-a662-676bcf5cfd75', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 18, 18, 'Everyone who divorces his wife, and marries another, commits adultery. He who marries one who is divorced from a husband commits adultery.'),
  ('823b1d9a-3aee-56fa-a8de-5f5edcca4844', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 19, 19, '"Now there was a certain rich man, and he was clothed in purple and fine linen, living in luxury every day.'),
  ('105ceea3-fa17-55f1-a1a1-83b213742171', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 20, 20, 'A certain beggar, named Lazarus, was laid at his gate, full of sores,'),
  ('23436a18-72a7-5bc3-a91c-9bc7dbbd8d85', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 21, 21, 'and desiring to be fed with the crumbs that fell from the rich man''s table. Yes, even the dogs came and licked his sores.'),
  ('efbe804d-ae2d-5fef-a49d-f2ed70d1f34f', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 22, 22, 'It happened that the beggar died, and that he was carried away by the angels to Abraham''s bosom. The rich man also died, and was buried.'),
  ('7055f09b-32da-5696-a190-169ffd3df505', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 23, 23, 'In Hades, he lifted up his eyes, being in torment, and saw Abraham far off, and Lazarus at his bosom.'),
  ('17d5af38-a293-55ac-ae37-3e6be0d0d7cb', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 24, 24, 'He cried and said, ''Father Abraham, have mercy on me, and send Lazarus, that he may dip the tip of his finger in water, and cool my tongue! For I am in anguish in this flame.'''),
  ('0ceb12bf-a75a-5b59-a34b-b8df29a65ce5', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 25, 25, '"But Abraham said, ''Son, remember that you, in your lifetime, received your good things, and Lazarus, in the same way, bad things. But now here he is comforted and you are in anguish.'),
  ('550937ea-a330-5ec9-addd-c2fb1fff0a6a', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 26, 26, 'Besides all this, between us and you there is a great gulf fixed, that those who want to pass from here to you are not able, and that none may cross over from there to us.'''),
  ('7820d2ba-fdfa-5a71-a722-1ae6bacfa005', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 27, 27, '"He said, ''I ask you therefore, father, that you would send him to my father''s house;'),
  ('d4bb204d-9791-5b51-a5e7-5b8708d353ae', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 28, 28, 'for I have five brothers, that he may testify to them, so they won''t also come into this place of torment.'''),
  ('eb64067f-f35d-5129-a38c-daf29e0b8d8a', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 29, 29, '"But Abraham said to him, ''They have Moses and the prophets. Let them listen to them.'''),
  ('169245f6-7714-532b-a340-e6f29d37c88e', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 30, 30, '"He said, ''No, father Abraham, but if one goes to them from the dead, they will repent.'''),
  ('94a3ead8-be3f-54a4-a4bb-eac0ceab0d51', 'cba56cac-5d53-5718-acfb-3ff698fa7174', NULL, 31, 31, '"He said to him, ''If they don''t listen to Moses and the prophets, neither will they be persuaded if one rises from the dead.''"'),
  ('151b75ce-7289-5f50-a64b-688356806143', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 1, 1, 'He said to the disciples, "It is impossible that no occasions of stumbling should come, but woe to him through whom they come!'),
  ('863e65df-b9f5-5495-ae49-431bc87d42cd', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 2, 2, 'It would be better for him if a millstone were hung around his neck, and he were thrown into the sea, rather than that he should cause one of these little ones to stumble.'),
  ('ef9a8aa7-cdbb-5034-af69-83d6e2b4ba18', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 3, 3, 'Be careful. If your brother sins against you, rebuke him. If he repents, forgive him.'),
  ('ce4151f6-aeaf-53f4-ac1c-9e0f0f7e3b2b', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 4, 4, 'If he sins against you seven times in the day, and seven times returns, saying, ''I repent,'' you shall forgive him."'),
  ('0e715323-a4d3-53ab-a9d4-da0e61361f51', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 5, 5, 'The apostles said to the Lord, "Increase our faith."'),
  ('f91d1717-e9fb-520e-a25f-ad2233b4d5cf', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 6, 6, 'The Lord said, "If you had faith like a grain of mustard seed, you would tell this sycamore tree, ''Be uprooted, and be planted in the sea,'' and it would obey you.'),
  ('27dc38be-414c-5291-af50-f2f1d5c0e157', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 7, 7, 'But who is there among you, having a servant plowing or keeping sheep, that will say, when he comes in from the field, ''Come immediately and sit down at the table,'''),
  ('159c23e2-76ad-511d-a30b-1883c5c58c72', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 8, 8, 'and will not rather tell him, ''Prepare my supper, clothe yourself properly, and serve me, while I eat and drink. Afterward you shall eat and drink''?'),
  ('a9f634b8-7082-5e13-a175-0b7e90927054', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 9, 9, 'Does he thank that servant because he did the things that were commanded? I think not.'),
  ('2e8516d5-aff8-5c38-a641-9eea472f33ec', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 10, 10, 'Even so you also, when you have done all the things that are commanded you, say, ''We are unworthy servants. We have done our duty.''"'),
  ('96491c5a-b64d-5b52-a48b-e3415be9f0ca', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 11, 11, 'It happened as he was on his way to Jerusalem, that he was passing along the borders of Samaria and Galilee.'),
  ('fb25e356-2312-5b3a-aa52-af1861b94fbc', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 12, 12, 'As he entered into a certain village, ten men who were lepers met him, who stood at a distance.'),
  ('06c08b82-2aaf-5f67-a8c2-9838b51c0506', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 13, 13, 'They lifted up their voices, saying, "Jesus, Master, have mercy on us!"'),
  ('1b9d3136-7df6-5b5b-a685-ab79e9219701', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 14, 14, 'When he saw them, he said to them, "Go and show yourselves to the priests." It happened that as they went, they were cleansed.'),
  ('a76902e4-d4dd-546b-ac76-f637ee597b87', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 15, 15, 'One of them, when he saw that he was healed, turned back, glorifying God with a loud voice.'),
  ('35c5d6aa-ddbe-5a37-a135-4e01199063a2', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 16, 16, 'He fell on his face at Jesus'' feet, giving him thanks; and he was a Samaritan.'),
  ('a29bdf4d-10b3-5330-ab87-0cfb829f0761', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 17, 17, 'Jesus answered, "Weren''t the ten cleansed? But where are the nine?'),
  ('df181b4c-0937-5270-a7a7-7bf7737ec097', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 18, 18, 'Were there none found who returned to give glory to God, except this stranger?"'),
  ('c8928fd7-0cbd-568f-a405-4bd9613d37fb', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 19, 19, 'Then he said to him, "Get up, and go your way. Your faith has healed you."'),
  ('084d767d-9439-594b-a645-5d81831241fd', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 20, 20, 'Being asked by the Pharisees when the Kingdom of God would come, he answered them, "The Kingdom of God doesn''t come with observation;'),
  ('c81640fe-efcf-53c2-a428-8bdf015a8493', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 21, 21, 'neither will they say, ''Look, here!'' or, ''Look, there!'' for behold, the Kingdom of God is within you."'),
  ('e824651a-3c80-51a8-aff1-7e92e317715d', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 22, 22, 'He said to the disciples, "The days will come, when you will desire to see one of the days of the Son of Man, and you will not see it.'),
  ('5905e43c-2298-5396-aaee-bf3b7c5bdf37', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 23, 23, 'They will tell you, ''Look, here!'' or ''Look, there!'' Don''t go away, nor follow after them,'),
  ('156da800-a82b-59e9-aec1-870f1f949387', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 24, 24, 'for as the lightning, when it flashes out of the one part under the sky, shines to the other part under the sky; so will the Son of Man be in his day.'),
  ('37ac91d7-d854-5b9d-a887-0bab2010851d', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 25, 25, 'But first, he must suffer many things and be rejected by this generation.'),
  ('7ff580a0-b097-5c24-a31b-283b1c918a5f', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 26, 26, 'As it happened in the days of Noah, even so will it be also in the days of the Son of Man.'),
  ('1cdf57d3-2fd3-583a-a8df-aa34339f4da8', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 27, 27, 'They ate, they drank, they married, they were given in marriage, until the day that Noah entered into the ship, and the flood came, and destroyed them all.'),
  ('d336d18a-240e-5bb0-aad2-8265c62d28b3', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 28, 28, 'Likewise, even as it happened in the days of Lot: they ate, they drank, they bought, they sold, they planted, they built;'),
  ('39400ff9-86d9-5395-a6f5-721839c37e3e', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 29, 29, 'but in the day that Lot went out from Sodom, it rained fire and sulfur from the sky, and destroyed them all.'),
  ('21cce465-c507-5997-a9e4-c27212fcb18d', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 30, 30, 'It will be the same way in the day that the Son of Man is revealed.'),
  ('2354d79e-5ffe-54e3-a460-267fa962d328', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 31, 31, 'In that day, he who will be on the housetop, and his goods in the house, let him not go down to take them away. Let him who is in the field likewise not turn back.'),
  ('9777c8a6-bcb4-5b6b-af6a-0d6c94d7d187', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 32, 32, 'Remember Lot''s wife!'),
  ('275fcd53-262a-53a3-a19c-3b098a80fe16', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 33, 33, 'Whoever seeks to save his life loses it, but whoever loses his life preserves it.'),
  ('0435822b-f332-5a9c-ae95-664e43a48936', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 34, 34, 'I tell you, in that night there will be two people in one bed. The one will be taken, and the other will be left.'),
  ('f085c601-fba5-59fe-a878-8d99af1d690e', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 35, 35, 'There will be two grinding grain together. One will be taken, and the other will be left."'),
  ('c26388bd-9652-5c0d-a6ea-76fc68daf30a', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 36, 36, ''),
  ('8b107505-9cd2-572c-a462-7fddaac1ad86', '094d5764-1832-5d53-aad6-0242ea8f0dae', NULL, 37, 37, 'They, answering, asked him, "Where, Lord?" He said to them, "Where the body is, there will the vultures also be gathered together."'),
  ('b062649c-75b5-5d2a-a1d6-8c34d18a1f16', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 1, 1, 'He also spoke a parable to them that they must always pray, and not give up,'),
  ('73d54722-28c0-5b5a-ab7f-597ca92677ca', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 2, 2, 'saying, "There was a judge in a certain city who didn''t fear God, and didn''t respect man.'),
  ('9d608446-40ae-5a1b-a858-503b709c1045', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 3, 3, 'A widow was in that city, and she often came to him, saying, ''Defend me from my adversary!'''),
  ('abc4be7d-ac79-5a43-a790-4de7cc6384a2', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 4, 4, 'He wouldn''t for a while, but afterward he said to himself, ''Though I neither fear God, nor respect man,'),
  ('6a78abec-138f-54da-ae47-eb8d269d094d', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 5, 5, 'yet because this widow bothers me, I will defend her, or else she will wear me out by her continual coming.''"'),
  ('139af927-b3e1-5aa3-abc1-c2063e3e2f0b', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 6, 6, 'The Lord said, "Listen to what the unrighteous judge says.'),
  ('9670fa41-a756-5e07-a92c-1196afb6df17', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 7, 7, 'Won''t God avenge his chosen ones, who are crying out to him day and night, and yet he exercises patience with them?'),
  ('be1581f9-e6ea-52eb-a100-01dc4a7f5479', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 8, 8, 'I tell you that he will avenge them quickly. Nevertheless, when the Son of Man comes, will he find faith on the earth?"'),
  ('fcabd766-1c27-5ca0-af29-4a8beab93f4b', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 9, 9, 'He spoke also this parable to certain people who were convinced of their own righteousness, and who despised all others.'),
  ('2f655efd-218f-5063-a32d-7e17c82734cf', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 10, 10, '"Two men went up into the temple to pray; one was a Pharisee, and the other was a tax collector.'),
  ('f0249dac-fdbf-5f29-a340-62e89e738ada', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 11, 11, 'The Pharisee stood and prayed to himself like this: ''God, I thank you, that I am not like the rest of men, extortioners, unrighteous, adulterers, or even like this tax collector.'),
  ('99a92546-072b-5f6e-a779-fb42e6365ebf', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 12, 12, 'I fast twice a week. I give tithes of all that I get.'''),
  ('2f3eaba5-270e-5aaf-a0cc-e845f69fbe2e', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 13, 13, 'But the tax collector, standing far away, wouldn''t even lift up his eyes to heaven, but beat his breast, saying, ''God, be merciful to me, a sinner!'''),
  ('e749a3c8-314d-54b9-a27f-d257c9bfdf1d', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 14, 14, 'I tell you, this man went down to his house justified rather than the other; for everyone who exalts himself will be humbled, but he who humbles himself will be exalted."'),
  ('7c6691cc-f570-5182-ae6f-b81433c466fb', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 15, 15, 'They were also bringing their babies to him, that he might touch them. But when the disciples saw it, they rebuked them.'),
  ('2be98b79-4155-5b33-a590-8330bee06c35', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 16, 16, 'Jesus summoned them, saying, "Allow the little children to come to me, and don''t hinder them, for the Kingdom of God belongs to such as these.'),
  ('0af7d250-3e22-588f-a87f-f62a9db9d00e', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 17, 17, 'Most certainly, I tell you, whoever doesn''t receive the Kingdom of God like a little child, he will in no way enter into it."'),
  ('9a148980-b15b-5c4f-ab10-78207ce0fc93', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 18, 18, 'A certain ruler asked him, saying, "Good Teacher, what shall I do to inherit eternal life?"'),
  ('935fd843-cba1-5dd6-ac33-d72a064aa225', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 19, 19, 'Jesus asked him, "Why do you call me good? No one is good, except one--God.'),
  ('86e254ba-6eb7-5ae1-a1cb-625d7adde96e', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 20, 20, 'You know the commandments: ''Don''t commit adultery,'' ''Don''t murder,'' ''Don''t steal,'' ''Don''t give false testimony,'' ''Honor your father and your mother.''"'),
  ('1fd1e800-1264-5c61-a567-801ce6d52d3f', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 21, 21, 'He said, "I have observed all these things from my youth up."'),
  ('e8864c5d-5a1c-5413-a894-6e84296698b7', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 22, 22, 'When Jesus heard these things, he said to him, "You still lack one thing. Sell all that you have, and distribute it to the poor. You will have treasure in heaven. Come, follow me."'),
  ('8174d14a-78d5-553c-ac54-86ff46cf158b', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 23, 23, 'But when he heard these things, he became very sad, for he was very rich.'),
  ('3cc53e4c-6363-5e2a-a0ac-8b2677dedb04', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 24, 24, 'Jesus, seeing that he became very sad, said, "How hard it is for those who have riches to enter into the Kingdom of God!'),
  ('8c82d056-ba89-5dc5-a3e0-a6463184d435', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 25, 25, 'For it is easier for a camel to enter in through a needle''s eye, than for a rich man to enter into the Kingdom of God."'),
  ('a1cecad1-9318-5b57-a0c0-851a73aeaa21', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 26, 26, 'Those who heard it said, "Then who can be saved?"'),
  ('3ff2fac4-d975-5efb-ad0a-d419ff381ead', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 27, 27, 'But he said, "The things which are impossible with men are possible with God."'),
  ('60a7db00-8883-531d-a5a4-55fb0e39cd61', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 28, 28, 'Peter said, "Look, we have left everything, and followed you."'),
  ('13145183-4f14-58ce-ab04-39ca56918439', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 29, 29, 'He said to them, "Most certainly I tell you, there is no one who has left house, or wife, or brothers, or parents, or children, for the Kingdom of God''s sake,'),
  ('ad1fa5a4-0883-5011-a65c-5e8179f3da96', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 30, 30, 'who will not receive many times more in this time, and in the world to come, eternal life."'),
  ('f16f504d-cd0a-5e37-a9e5-3216e1cada10', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 31, 31, 'He took the twelve aside, and said to them, "Behold, we are going up to Jerusalem, and all the things that are written through the prophets concerning the Son of Man will be completed.'),
  ('ab9baaab-bb1f-5826-a23d-8fc2b0839570', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 32, 32, 'For he will be delivered up to the Gentiles, will be mocked, treated shamefully, and spit on.'),
  ('e22314e9-8f01-593c-ac08-b7b3b588a6b5', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 33, 33, 'They will scourge and kill him. On the third day, he will rise again."'),
  ('262c27e8-0513-5a77-a820-27134389e04b', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 34, 34, 'They understood none of these things. This saying was hidden from them, and they didn''t understand the things that were said.'),
  ('90d9bda9-dcf7-54eb-a841-181f0c8447d2', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 35, 35, 'It happened, as he came near Jericho, a certain blind man sat by the road, begging.'),
  ('921de062-f39f-5bb3-a290-500444c70c44', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 36, 36, 'Hearing a multitude going by, he asked what this meant.'),
  ('2ce36a35-614b-5162-a788-f60f69ef3248', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 37, 37, 'They told him that Jesus of Nazareth was passing by.'),
  ('e8cf938b-9c38-56f0-a6b5-47686ef0f2b6', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 38, 38, 'He cried out, "Jesus, you son of David, have mercy on me!"'),
  ('6b7adfdd-5108-5513-ac04-c06bbf0eeac8', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 39, 39, 'Those who led the way rebuked him, that he should be quiet; but he cried out all the more, "You son of David, have mercy on me!"'),
  ('0b6b3162-92fd-5f5d-a500-817ab61fef12', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 40, 40, 'Standing still, Jesus commanded him to be brought to him. When he had come near, he asked him,'),
  ('2dda2f5a-516b-57c9-a5d5-489b2bcf6a4f', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 41, 41, '"What do you want me to do?" He said, "Lord, that I may see again."'),
  ('fd75cd7f-978e-5f3e-a436-582686ca05f2', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 42, 42, 'Jesus said to him, "Receive your sight. Your faith has healed you."'),
  ('15ec4c4a-597a-5fe8-a8cd-4394ebd8b2c9', '15817f8f-1e98-5b45-abf9-d79916f4f1c8', NULL, 43, 43, 'Immediately he received his sight, and followed him, glorifying God. All the people, when they saw it, praised God.'),
  ('7e52ef32-0c54-5e85-a913-1b673202d1e6', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 1, 1, 'He entered and was passing through Jericho.'),
  ('b5fd795c-3691-5d94-afdb-b6d37d4692ea', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 2, 2, 'There was a man named Zacchaeus. He was a chief tax collector, and he was rich.'),
  ('4486ec2f-bb92-5493-a50e-6a852f8ea2c0', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 3, 3, 'He was trying to see who Jesus was, and couldn''t because of the crowd, because he was short.'),
  ('28b79bc3-fe51-53a1-a116-b4a9c1e66cab', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 4, 4, 'He ran on ahead, and climbed up into a sycamore tree to see him, for he was to pass that way.'),
  ('02e60829-adfd-5bee-a6d9-2bc5da4173fe', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 5, 5, 'When Jesus came to the place, he looked up and saw him, and said to him, "Zacchaeus, hurry and come down, for today I must stay at your house."'),
  ('6cb938fe-ee15-5cbc-a28d-5dfa615f11e9', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 6, 6, 'He hurried, came down, and received him joyfully.'),
  ('8516463e-d904-5a56-a27f-8f4ffed9e8bc', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 7, 7, 'When they saw it, they all murmured, saying, "He has gone in to lodge with a man who is a sinner."'),
  ('b9452df8-12c8-5b39-ace5-97ab106b3e55', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 8, 8, 'Zacchaeus stood and said to the Lord, "Behold, Lord, half of my goods I give to the poor. If I have wrongfully exacted anything of anyone, I restore four times as much."'),
  ('0f82f34b-0774-5de7-abfd-729ad6f06bec', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 9, 9, 'Jesus said to him, "Today, salvation has come to this house, because he also is a son of Abraham.'),
  ('610d0134-33cb-5861-a181-b138183de6ea', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 10, 10, 'For the Son of Man came to seek and to save that which was lost."'),
  ('9692ebc3-a144-5c98-a5bf-c6682a96dec2', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 11, 11, 'As they heard these things, he went on and told a parable, because he was near Jerusalem, and they supposed that the Kingdom of God would be revealed immediately.'),
  ('31e4eaaa-5ef7-5d6b-abff-49f252e61f5b', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 12, 12, 'He said therefore, "A certain nobleman went into a far country to receive for himself a kingdom, and to return.'),
  ('71555e05-2c56-5503-a900-61fc75117bf1', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 13, 13, 'He called ten servants of his, and gave them ten mina coins, and told them, ''Conduct business until I come.'''),
  ('4b7ce24d-9e74-56f8-adff-8617c9c0f1fb', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 14, 14, 'But his citizens hated him, and sent an envoy after him, saying, ''We don''t want this man to reign over us.'''),
  ('62f27896-57a4-5d51-a867-f4ebb2673a7f', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 15, 15, '"It happened when he had come back again, having received the kingdom, that he commanded these servants, to whom he had given the money, to be called to him, that he might know what they had gained by conducting business.'),
  ('64a6c70f-0a0d-5e5d-a09e-0a24bbf4767a', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 16, 16, 'The first came before him, saying, ''Lord, your mina has made ten more minas.'''),
  ('0384094b-43c3-532e-aab4-65baa709d48e', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 17, 17, '"He said to him, ''Well done, you good servant! Because you were found faithful with very little, you shall have authority over ten cities.'''),
  ('cda8ce7d-0fbb-5198-af25-d5c141e8d34f', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 18, 18, '"The second came, saying, ''Your mina, Lord, has made five minas.'''),
  ('6007f583-95a8-5a6e-ae1d-b159c29b81b3', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 19, 19, '"So he said to him, ''And you are to be over five cities.'''),
  ('fba3dc75-ad41-5604-aca6-8de3a8e1fd07', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 20, 20, 'Another came, saying, ''Lord, behold, your mina, which I kept laid away in a handkerchief,'),
  ('af05805a-b1ff-5db9-af57-c87b6c7c2d9b', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 21, 21, 'for I feared you, because you are an exacting man. You take up that which you didn''t lay down, and reap that which you didn''t sow.'''),
  ('b8ef4f76-f74c-56b6-a1c7-3be5d4efe74b', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 22, 22, '"He said to him, ''Out of your own mouth will I judge you, you wicked servant! You knew that I am an exacting man, taking up that which I didn''t lay down, and reaping that which I didn''t sow.'),
  ('1e0eb6b1-96ff-5240-ae91-b31e3ba59ab1', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 23, 23, 'Then why didn''t you deposit my money in the bank, and at my coming, I might have earned interest on it?'''),
  ('8eab46c5-5100-51b8-ac89-11f2b42e950b', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 24, 24, 'He said to those who stood by, ''Take the mina away from him, and give it to him who has the ten minas.'''),
  ('569ef3ba-2dc2-5ee5-acac-bb2341fdef10', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 25, 25, '"They said to him, ''Lord, he has ten minas!'''),
  ('5fb417cb-318a-5bb0-aba4-0f1ab9eecdf2', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 26, 26, '''For I tell you that to everyone who has, will more be given; but from him who doesn''t have, even that which he has will be taken away from him.'),
  ('c550e13c-7f2f-574f-a0a2-8a18fab185dc', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 27, 27, 'But bring those enemies of mine who didn''t want me to reign over them here, and kill them before me.''"'),
  ('fc17fb5a-10b4-5ee9-abc0-5e36fb7d1a6b', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 28, 28, 'Having said these things, he went on ahead, going up to Jerusalem.'),
  ('f98129a8-915b-58aa-a297-f23eeeb5a5df', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 29, 29, 'It happened, when he drew near to Bethsphage and Bethany, at the mountain that is called Olivet, he sent two of his disciples,'),
  ('7cde2fe5-b30b-514f-a405-7e146ae2ca03', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 30, 30, 'saying, "Go your way into the village on the other side, in which, as you enter, you will find a colt tied, whereon no man ever yet sat. Untie it, and bring it.'),
  ('eb44fc73-7a10-5f73-af08-82b6936c52b9', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 31, 31, 'If anyone asks you, ''Why are you untying it?'' say to him: ''The Lord needs it.''"'),
  ('1914c3df-f83d-566f-a0c6-3bb5192ff298', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 32, 32, 'Those who were sent went away, and found things just as he had told them.'),
  ('a9c348c3-0e62-55d2-a8b2-d5f6089c060f', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 33, 33, 'As they were untying the colt, its owners said to them, "Why are you untying the colt?"'),
  ('2ab17451-fb5d-5167-aa2c-a25202abe1f5', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 34, 34, 'They said, "The Lord needs it."'),
  ('2b8646a5-cc52-5aa7-a703-5b5c2116a341', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 35, 35, 'They brought it to Jesus. They threw their cloaks on the colt, and set Jesus on them.'),
  ('bd3bb548-25f8-53de-a20f-d74a5b090185', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 36, 36, 'As he went, they spread their cloaks in the way.'),
  ('e195e5bc-a48e-575d-a809-6f6b9144bffb', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 37, 37, 'As he was now getting near, at the descent of the Mount of Olives, the whole multitude of the disciples began to rejoice and praise God with a loud voice for all the mighty works which they had seen,'),
  ('49d41d3a-22f8-5498-a36c-1be4e665674d', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 38, 38, 'saying, "Blessed is the King who comes in the name of the Lord! Peace in heaven, and glory in the highest!"'),
  ('8f5266cc-f714-57d4-aad8-d8542ba0ae4f', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 39, 39, 'Some of the Pharisees from the multitude said to him, "Teacher, rebuke your disciples!"'),
  ('f18913a5-e9e6-5110-a6ef-7c0cf1a2b670', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 40, 40, 'He answered them, "I tell you that if these were silent, the stones would cry out."'),
  ('b51e302f-32c1-562e-abaf-cba02a21b1dd', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 41, 41, 'When he drew near, he saw the city and wept over it,'),
  ('225e04e5-f53a-5cb6-a332-d51a5fe97e0c', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 42, 42, 'saying, "If you, even you, had known today the things which belong to your peace! But now, they are hidden from your eyes.'),
  ('fe84eba0-2c5f-5234-aa22-dc94865303e9', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 43, 43, 'For the days will come on you, when your enemies will throw up a barricade against you, surround you, hem you in on every side,'),
  ('0aaaa2f7-276e-57b6-ab33-f189fc49ba38', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 44, 44, 'and will dash you and your children within you to the ground. They will not leave in you one stone on another, because you didn''t know the time of your visitation."'),
  ('88e38516-2765-5c55-ab7d-38b9891f2f6f', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 45, 45, 'He entered into the temple, and began to drive out those who bought and sold in it,'),
  ('e93cdc3f-eca6-524a-add8-2972238c7299', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 46, 46, 'saying to them, "It is written, ''My house is a house of prayer,'' but you have made it a ''den of robbers''!"'),
  ('4632e67f-1a64-50a8-a80b-dc213e658d92', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 47, 47, 'He was teaching daily in the temple, but the chief priests and the scribes and the leading men among the people sought to destroy him.'),
  ('8e11a5f5-301f-5593-ac3b-a7d66adf0af7', 'b706d309-3dff-5294-a9ee-dc0c6ca311d3', NULL, 48, 48, 'They couldn''t find what they might do, for all the people hung on to every word that he said.'),
  ('02021a94-2840-5e24-af66-cbafa109c485', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 1, 1, 'It happened on one of those days, as he was teaching the people in the temple and preaching the Good News, that the priests and scribes came to him with the elders.'),
  ('7d9eccb0-4f27-5e5c-ab47-937536bc6e66', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 2, 2, 'They asked him, "Tell us: by what authority do you do these things? Or who is giving you this authority?"'),
  ('541bd40d-f16c-5142-ac5c-28ceb12b1c48', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 3, 3, 'He answered them, "I also will ask you one question. Tell me:'),
  ('d3b6a7e2-ddfe-56a8-a13a-3cdcd32231c2', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 4, 4, 'the baptism of John, was it from heaven, or from men?"'),
  ('4ea50770-1868-5545-a97f-059815a2d139', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 5, 5, 'They reasoned with themselves, saying, "If we say, ''From heaven,'' he will say, ''Why didn''t you believe him?'''),
  ('c51bff7f-beef-562f-a406-5cb53d4eeaa5', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 6, 6, 'But if we say, ''From men,'' all the people will stone us, for they are persuaded that John was a prophet."'),
  ('aeebdeee-a3a1-59a6-a071-eb73a8a30a69', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 7, 7, 'They answered that they didn''t know where it was from.'),
  ('1ad0e16d-a668-537f-a50a-bd84c85c5333', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 8, 8, 'Jesus said to them, "Neither will I tell you by what authority I do these things."'),
  ('a12c79dc-36ca-53ba-a191-37abe3992501', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 9, 9, 'He began to tell the people this parable. "A man planted a vineyard, and rented it out to some farmers, and went into another country for a long time.'),
  ('f4e7a089-af1d-526a-a806-3e467b64e1a4', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 10, 10, 'At the proper season, he sent a servant to the farmers to collect his share of the fruit of the vineyard. But the farmers beat him, and sent him away empty.'),
  ('0e7afc4e-0cbe-545f-ac48-5e65efdff862', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 11, 11, 'He sent yet another servant, and they also beat him, and treated him shamefully, and sent him away empty.'),
  ('734e47b2-0abc-537b-a628-4c587508e7de', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 12, 12, 'He sent yet a third, and they also wounded him, and threw him out.'),
  ('b1f4d2d8-c2b1-5254-a205-447fd401af27', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 13, 13, 'The lord of the vineyard said, ''What shall I do? I will send my beloved son. It may be that seeing him, they will respect him.'''),
  ('194b7bea-b13f-5e46-a4c2-1b796e3d4e72', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 14, 14, '"But when the farmers saw him, they reasoned among themselves, saying, ''This is the heir. Come, let''s kill him, that the inheritance may be ours.'''),
  ('2bfa98d3-67a4-5633-acc3-a32b75052fa2', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 15, 15, 'They threw him out of the vineyard, and killed him. What therefore will the lord of the vineyard do to them?'),
  ('86b52fbc-51ba-5cf3-a361-44f593908e4b', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 16, 16, 'He will come and destroy these farmers, and will give the vineyard to others." When they heard it, they said, "May it never be!"'),
  ('8d9fd5d5-99c6-5b07-a001-fb03e22f46d2', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 17, 17, 'But he looked at them, and said, "Then what is this that is written, ''The stone which the builders rejected, the same was made the chief cornerstone?'''),
  ('38171fef-286a-531f-a30a-d64c15594346', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 18, 18, 'Everyone who falls on that stone will be broken to pieces, but it will crush whomever it falls on to dust."'),
  ('9807fc0d-a127-5725-a712-9869010d195c', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 19, 19, 'The chief priests and the scribes sought to lay hands on him that very hour, but they feared the people--for they knew he had spoken this parable against them.'),
  ('41843edf-db89-519b-a76b-5aeb68824815', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 20, 20, 'They watched him, and sent out spies, who pretended to be righteous, that they might trap him in something he said, so as to deliver him up to the power and authority of the governor.'),
  ('aa1d1d19-4157-593b-ae3a-d347bc11a204', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 21, 21, 'They asked him, "Teacher, we know that you say and teach what is right, and aren''t partial to anyone, but truly teach the way of God.'),
  ('0a3b8ef9-5afc-50aa-aca8-f249b5ac0f46', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 22, 22, 'Is it lawful for us to pay taxes to Caesar, or not?"'),
  ('2d39bbb9-77ed-5c09-a2d8-d78dabaecfcc', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 23, 23, 'But he perceived their craftiness, and said to them, "Why do you test me?'),
  ('7c7dd744-5cbe-5360-aa96-d2b9f6d5125f', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 24, 24, 'Show me a denarius. Whose image and inscription are on it?" They answered, "Caesar''s."'),
  ('19610a20-3d76-558b-a11c-f128a97ac92a', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 25, 25, 'He said to them, "Then give to Caesar the things that are Caesar''s, and to God the things that are God''s."'),
  ('51ccd788-7723-5236-a437-951fb01128d0', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 26, 26, 'They weren''t able to trap him in his words before the people. They marveled at his answer, and were silent.'),
  ('acbb1fe4-f41f-539c-aff4-b8101cd1d07a', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 27, 27, 'Some of the Sadducees came to him, those who deny that there is a resurrection.'),
  ('a9b7cc62-247d-5836-a022-5b971a96c98c', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 28, 28, 'They asked him, "Teacher, Moses wrote to us that if a man''s brother dies having a wife, and he is childless, his brother should take the wife, and raise up children for his brother.'),
  ('0d060c5b-c512-5fe1-a546-584b016693f6', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 29, 29, 'There were therefore seven brothers. The first took a wife, and died childless.'),
  ('ccff953e-4c5d-57af-af25-c28d0859eaf7', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 30, 30, 'The second took her as wife, and he died childless.'),
  ('c19f2029-0938-504a-a5d1-303946710db3', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 31, 31, 'The third took her, and likewise the seven all left no children, and died.'),
  ('2fc24019-0fce-5e0f-a12c-e40363449806', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 32, 32, 'Afterward the woman also died.'),
  ('79ba9014-8a64-5536-adc7-a711d3d107ba', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 33, 33, 'Therefore in the resurrection whose wife of them will she be? For the seven had her as a wife."'),
  ('ce7b497d-f8da-5647-afd1-d3e8a6b5b62b', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 34, 34, 'Jesus said to them, "The children of this age marry, and are given in marriage.'),
  ('51ab225c-679c-5972-a30a-6285949d47b8', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 35, 35, 'But those who are considered worthy to attain to that age and the resurrection from the dead, neither marry, nor are given in marriage.'),
  ('472e8d18-1ad4-5002-a0d7-64d7c98239ae', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 36, 36, 'For they can''t die any more, for they are like the angels, and are children of God, being children of the resurrection.'),
  ('73538ad1-b00b-59a6-ab86-a93fe32b1974', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 37, 37, 'But that the dead are raised, even Moses showed at the bush, when he called the Lord ''The God of Abraham, the God of Isaac, and the God of Jacob.'''),
  ('9f9bc502-073c-5767-ad82-bceac6cd81a3', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 38, 38, 'Now he is not the God of the dead, but of the living, for all are alive to him."'),
  ('243181a9-95a4-573b-ad97-1a4bdb84c856', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 39, 39, 'Some of the scribes answered, "Teacher, you speak well."'),
  ('a570589b-e4f3-541f-afa6-cc977e1706ad', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 40, 40, 'They didn''t dare to ask him any more questions.'),
  ('37350fe5-0999-504e-a8d7-d0f274970502', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 41, 41, 'He said to them, "Why do they say that the Christ is David''s son?'),
  ('0a2e601f-2ded-5c20-a3bd-8724fe27026e', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 42, 42, 'David himself says in the book of Psalms, ''The Lord said to my Lord, "Sit at my right hand,'),
  ('c0afa968-265e-5e34-adeb-0e28a1858fcd', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 43, 43, 'until I make your enemies the footstool of your feet."'''),
  ('e6e1979d-e872-576b-aa32-7d5094cde8af', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 44, 44, '"David therefore calls him Lord, so how is he his son?"'),
  ('c1ce807c-7e90-5b46-a00c-2f49acfe4d6b', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 45, 45, 'In the hearing of all the people, he said to his disciples,'),
  ('65a57ea1-df2c-5f1e-a89d-049e30b278f1', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 46, 46, '"Beware of the scribes, who like to walk in long robes, and love greetings in the marketplaces, the best seats in the synagogues, and the best places at feasts;'),
  ('3da4cbb5-6897-5fb4-a533-6a6c2057fcae', 'a64dcfe1-6395-5452-a327-afede367a4e6', NULL, 47, 47, 'who devour widows'' houses, and for a pretense make long prayers: these will receive greater condemnation."'),
  ('81aee450-0766-5fa0-a03b-611195e74166', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 1, 1, 'He looked up, and saw the rich people who were putting their gifts into the treasury.'),
  ('00df66ec-f610-5845-a291-6746aaf127a6', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 2, 2, 'He saw a certain poor widow casting in two small brass coins.'),
  ('89f89c35-70f6-54d0-a24a-5c63895f94d7', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 3, 3, 'He said, "Truly I tell you, this poor widow put in more than all of them,'),
  ('85762f3b-6b71-55ad-ac66-a39cd24f715e', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 4, 4, 'for all these put in gifts for God from their abundance, but she, out of her poverty, put in all that she had to live on."'),
  ('c224d992-4e8c-5da6-aa55-13d3bd583135', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 5, 5, 'As some were talking about the temple and how it was decorated with beautiful stones and gifts, he said,'),
  ('49b59d48-7606-5463-a64e-5399987ec075', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 6, 6, '"As for these things which you see, the days will come, in which there will not be left here one stone on another that will not be thrown down."'),
  ('aa348968-706e-5801-a602-0dd4a522b888', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 7, 7, 'They asked him, "Teacher, so when will these things be? What is the sign that these things are about to happen?"'),
  ('370568f8-8ff7-59b2-ad36-726a71014765', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 8, 8, 'He said, "Watch out that you don''t get led astray, for many will come in my name, saying, ''I am he,'' and, ''The time is at hand.'' Therefore don''t follow them.'),
  ('064bb1a9-9361-57d6-acba-ed15bf7ff071', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 9, 9, 'When you hear of wars and disturbances, don''t be terrified, for these things must happen first, but the end won''t come immediately."'),
  ('cf4e6a6c-280c-54e7-a513-cd9efe15c3e7', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 10, 10, 'Then he said to them, "Nation will rise against nation, and kingdom against kingdom.'),
  ('b35f3aff-7c80-573d-acd0-a2e12e318b94', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 11, 11, 'There will be great earthquakes, famines, and plagues in various places. There will be terrors and great signs from heaven.'),
  ('f13e4e09-b465-5a8d-a0b5-4a4e1eb4d3dd', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 12, 12, 'But before all these things, they will lay their hands on you and will persecute you, delivering you up to synagogues and prisons, bringing you before kings and governors for my name''s sake.'),
  ('8f3ea4e7-4fa9-5199-a941-9d48acfa83bf', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 13, 13, 'It will turn out as a testimony for you.'),
  ('b46cb128-d5e4-5696-ab52-eb805894e966', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 14, 14, 'Settle it therefore in your hearts not to meditate beforehand how to answer,'),
  ('40c8b65c-372a-5b39-a4eb-315cdcd9187f', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 15, 15, 'for I will give you a mouth and wisdom which all your adversaries will not be able to withstand or to contradict.'),
  ('0a930961-8146-5f2e-a2e8-6eae8d05d199', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 16, 16, 'You will be handed over even by parents, brothers, relatives, and friends. They will cause some of you to be put to death.'),
  ('14a4621c-b716-5dc1-a893-535489183443', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 17, 17, 'You will be hated by all men for my name''s sake.'),
  ('0b67ae01-8bac-5eae-a07a-0b3b03e1da53', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 18, 18, 'And not a hair of your head will perish.'),
  ('eeed3059-21d1-5124-a79e-456cb6db5d4c', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 19, 19, '"By your endurance you will win your lives.'),
  ('85034db3-4f58-5dfb-ab1c-5d2a728a70b0', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 20, 20, '"But when you see Jerusalem surrounded by armies, then know that its desolation is at hand.'),
  ('608e0ec0-b5bb-5e7a-a9ba-eec714e8189b', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 21, 21, 'Then let those who are in Judea flee to the mountains. Let those who are in the midst of her depart. Let those who are in the country not enter therein.'),
  ('b53b2c55-191d-5d44-abbd-461fa08e8823', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 22, 22, 'For these are days of vengeance, that all things which are written may be fulfilled.'),
  ('06a8a02a-2fc4-549d-ae44-d7179b7fc923', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 23, 23, 'Woe to those who are pregnant and to those who nurse infants in those days! For there will be great distress in the land, and wrath to this people.'),
  ('986dfaef-03f8-5b09-a5e9-3cd0736e2035', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 24, 24, 'They will fall by the edge of the sword, and will be led captive into all the nations. Jerusalem will be trampled down by the Gentiles, until the times of the Gentiles are fulfilled.'),
  ('40ecc3c3-b9ca-58e1-a0d5-b01b5d8a9bb7', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 25, 25, 'There will be signs in the sun, moon, and stars; and on the earth anxiety of nations, in perplexity for the roaring of the sea and the waves;'),
  ('9115d530-d3c7-556c-a2ea-62175690ea5a', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 26, 26, 'men fainting for fear, and for expectation of the things which are coming on the world: for the powers of the heavens will be shaken.'),
  ('4fb0699e-0947-5114-a905-083d81f3fa80', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 27, 27, 'Then they will see the Son of Man coming in a cloud with power and great glory.'),
  ('aa3e60cd-9b57-50a7-a9a0-bc280f79c375', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 28, 28, 'But when these things begin to happen, look up, and lift up your heads, because your redemption is near."'),
  ('fc776526-0037-5440-a777-84a84793372a', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 29, 29, 'He told them a parable. "See the fig tree, and all the trees.'),
  ('02834231-7604-5274-a6f9-042614d9e942', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 30, 30, 'When they are already budding, you see it and know by your own selves that the summer is already near.'),
  ('a0f80ad4-6eff-51aa-a2d1-21919d407e1b', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 31, 31, 'Even so you also, when you see these things happening, know that the Kingdom of God is near.'),
  ('88f2c7db-9fdd-5f62-aafe-00af08d95971', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 32, 32, 'Most certainly I tell you, this generation will not pass away until all things are accomplished.'),
  ('fe9ba36e-b77a-54ff-a821-05dfb8584268', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 33, 33, 'Heaven and earth will pass away, but my words will by no means pass away.'),
  ('a2bb12ec-d9fe-52f7-a98d-9f6c3d550cb6', '576b7bf6-6759-50b0-abbb-fedfafc2585b', NULL, 34, 34, '"So be careful, or your hearts will be loaded down with carousing, drunkenness, and cares of this life, and that day will come on you suddenly.')
